insert into public.courses (id, slug, title, description, title_nl, description_nl, published) values
  ('627837c6-f8a7-5a58-8da2-afcb16683b36', 'ai-web-developer', 'AI Web Developer', 'From your first Claude prompt to a complete production-ready website.', 'AI Web Developer', 'Van je eerste Claude-prompt tot een complete website die klaar is voor productie.', true)
insert into public.levels (id, course_id, slug, title, description, title_nl, description_nl, position, published) values
  ('0117796f-d1ee-5e5a-8132-f58c5592b527', '627837c6-f8a7-5a58-8da2-afcb16683b36', 'think-like-a-builder', 'Think Like a Builder', 'Understand how websites are actually put together, and what changes when an AI writes the code.', 'Denk als een bouwer', 'Begrijp hoe websites echt in elkaar zitten, en wat er verandert als een AI de code schrijft.', 1, true),
  ('dc1a60ee-68f1-5dfe-908c-65b35b975f35', '627837c6-f8a7-5a58-8da2-afcb16683b36', 'mastering-claude', 'Mastering Claude', 'Learn to direct a model instead of hoping for a good answer: context, constraints, design direction, existing code.', 'Claude beheersen', 'Leer een model aansturen in plaats van te hopen op een goed antwoord: context, beperkingen, ontwerprichting, bestaande code.', 2, true),
  ('4b9dbcc2-d326-51f9-913a-3d45622166bd', '627837c6-f8a7-5a58-8da2-afcb16683b36', 'your-first-website', 'Your First Website', 'Take one idea from an empty folder to a responsive page that works on a phone.', 'Je eerste website', 'Breng één idee van een lege map naar een responsive pagina die werkt op een telefoon.', 3, true),
  ('d6c8b7b8-d769-54cf-9cf3-f6a1f8f59db0', '627837c6-f8a7-5a58-8da2-afcb16683b36', 'prompt-engineering-for-developers', 'Prompt Engineering for Developers', 'The nine prompt shapes that do the work, and how to chain them into a session that goes somewhere.', 'Prompt engineering voor developers', 'De negen promptvormen die het werk doen, en hoe je ze aan elkaar rijgt tot een sessie die ergens komt.', 4, true),
  ('0a9dece4-ba97-5f92-8552-476a68ade471', '627837c6-f8a7-5a58-8da2-afcb16683b36', 'build-like-a-professional', 'Build Like a Professional', 'The difference between a page that works and a page a studio would ship.', 'Bouw als een professional', 'Het verschil tussen een pagina die werkt en een pagina die een studio zou opleveren.', 5, true),
  ('b879945d-7b93-55d1-b6e5-878439a89c29', '627837c6-f8a7-5a58-8da2-afcb16683b36', 'debugging-with-claude', 'Debugging with Claude', 'Read the failure, describe it precisely, and verify the fix instead of trusting it.', 'Debuggen met Claude', 'Lees de fout, beschrijf hem precies, en controleer de oplossing in plaats van erop te vertrouwen.', 6, true),
  ('6eb9b656-1b10-570e-9111-dd18aab1a90d', '627837c6-f8a7-5a58-8da2-afcb16683b36', 'advanced-web-building', 'Advanced Web Building', 'Layout, state, data and architecture — the parts a generated page usually gets wrong.', 'Gevorderd webbouwen', 'Layout, state, data en architectuur — de onderdelen waar een gegenereerde pagina meestal de mist in gaat.', 7, true),
  ('0e3df840-08ac-5805-9967-87d6016c8ea8', '627837c6-f8a7-5a58-8da2-afcb16683b36', 'ship-it', 'Ship It', 'Test it, tighten it, put it online, and check the things that only break in public.', 'Zet hem live', 'Test hem, scherp hem aan, zet hem online en controleer de dingen die alleen in het openbaar stukgaan.', 8, true)
insert into public.lessons (id, level_id, slug, title, description, content, title_nl, description_nl, content_nl, position, published, estimated_minutes, video_url, video_duration) values
  ('097d8418-6285-5066-bc1a-ec7576676130', '0117796f-d1ee-5e5a-8132-f58c5592b527', 'what-is-ai-assisted-development', 'What is AI-assisted development?', 'The job did not disappear. It moved.', '[{"t": "h", "text": "The work moved. It did not vanish."}, {"t": "p", "text": "There is a story going around that AI writes the website now and you just ask nicely. It is wrong in a specific and useful way. A model can produce a page faster than any human can type one. What it cannot do is decide whether that page is the right page — and that decision is most of the job."}, {"t": "p", "text": "So the work moves. Away from remembering syntax, towards **deciding, directing, reading and judging**. You will still open a code editor. You will spend less time typing into it and far more time looking at what came back and asking whether it deserves to ship."}, {"t": "figure", "kind": "shift", "caption": "What a developer spends time on, before and after"}, {"t": "h", "text": "What actually changes"}, {"t": "p", "text": "Three things get dramatically cheaper: the first draft, the boring parts, and the explanation. A layout that used to cost an afternoon costs a minute. A regular expression you would have looked up costs nothing. An unfamiliar piece of code can be explained back to you line by line."}, {"t": "p", "text": "Three things get no cheaper at all: knowing what to build, knowing whether it is good, and being responsible for it when it breaks. Those are the parts a client is actually paying for, and they are the parts this course is about."}, {"t": "callout", "kind": "note", "title": "The uncomfortable version", "text": "If your only skill is producing code that works, that skill is now commodity. If you can decide what should exist, direct a model towards it, and tell the difference between good and merely working — you have more leverage than you have ever had."}, {"t": "h", "text": "Generation is not the hard part"}, {"t": "p", "text": "Watch someone new to this and you will see the same pattern. They ask for a website. They get one. It looks plausible. They ask for a change. They get a different plausible thing, and something that worked before quietly stops working. Twenty minutes later they have a folder of code nobody understands, including them."}, {"t": "p", "text": "Nothing went wrong technically. What went wrong is that no one was steering. Every prompt was a fresh wish rather than a step in a build."}, {"t": "demo", "kind": "context-compare", "title": "The same request, two ways"}, {"t": "h", "text": "The mental model that works"}, {"t": "p", "text": "Treat the model as an extremely fast, extremely well-read colleague who has never seen your project, has no opinion about your client, and will do exactly what you asked rather than what you meant. That colleague is genuinely valuable. They are not a replacement for knowing what you want."}, {"t": "list", "items": ["You decide what to build. The model proposes how.", "You give context. Without it, you get the average of everything it has ever read.", "You read the output. Not to admire it — to judge it.", "You own the result. The model is not on the invoice."]}, {"t": "prompt", "n": "01", "title": "A first prompt that earns its place", "body": "I am learning AI-assisted web development. Explain, in plain language and in under 200 words, the difference between what a browser downloads and what a server does. Assume I have never written code. Use one concrete example: someone opening a bakery''s website on their phone.", "why": {"context": "It states who you are and what you already know, so the answer is pitched at you rather than at nobody.", "constraints": "Under 200 words, plain language, one example. Each one rules out a kind of answer you did not want.", "output": "An explanation, not code — which is the right output for the question being asked.", "iteration": "If a sentence loses you, quote it back and ask for that sentence alone to be re-explained. Do not restart."}}, {"t": "task", "title": "Try it before the next lesson", "steps": ["Open Claude and run the prompt above, unchanged.", "Read the answer and find the one sentence you are least sure about.", "Quote that sentence back and ask for it to be explained differently.", "Notice how much better the second answer is — and that the improvement came from you, not the model."], "done": "You have had a conversation rather than made a request. That distinction is the whole course."}, {"t": "quiz", "q": "What gets cheaper with AI assistance, and what does not?", "type": "single", "options": ["Everything gets cheaper at roughly the same rate", "Producing code gets much cheaper; deciding what to build and judging quality do not", "Only boilerplate gets cheaper; real code is unaffected", "Nothing changes, the tools are just faster autocomplete"], "correct": [1], "why": "First drafts and boilerplate collapse in cost. Judgement, taste and responsibility do not move at all — which is why they are where your value now sits."}, {"t": "summary", "points": ["The work moved from typing to deciding, directing, reading and judging.", "Generation is the cheap half. Steering is the half that is worth money.", "Treat the model as a fast colleague with no context, not as an oracle.", "You own the output, so you have to be able to read it."]}]'::jsonb, 'Wat is AI-ondersteund ontwikkelen?', 'Het vak is niet verdwenen. Het is verschoven.', '[{"t": "h", "text": "Het werk is verschoven. Het is niet verdwenen."}, {"t": "p", "text": "Er gaat een verhaal rond dat AI de website nu schrijft en dat jij alleen nog netjes hoeft te vragen. Dat klopt niet, op een specifieke en bruikbare manier. Een model maakt een pagina sneller dan welke mens die ook kan typen. Wat het niet kan, is bepalen of dat de juiste pagina is — en die beslissing is het grootste deel van het werk."}, {"t": "p", "text": "Dus verschuift het werk. Weg van syntaxis onthouden, richting **beslissen, sturen, lezen en beoordelen**. Je opent nog steeds een code-editor. Je typt er minder in en kijkt veel langer naar wat eruit komt, met de vraag of het het verdient om live te gaan."}, {"t": "figure", "kind": "shift", "caption": "Waar een developer zijn tijd aan besteedt, voor en na"}, {"t": "h", "text": "Wat er echt verandert"}, {"t": "p", "text": "Drie dingen worden dramatisch goedkoper: de eerste versie, de saaie stukken en de uitleg. Een layout die eerst een middag kostte, kost nu een minuut. Een reguliere expressie die je had moeten opzoeken, kost niets. Een stuk code dat je niet kent, wordt regel voor regel aan je uitgelegd."}, {"t": "p", "text": "Drie dingen worden geen cent goedkoper: weten wat je moet bouwen, weten of het goed is, en verantwoordelijk zijn als het stukgaat. Dat is waar een klant in werkelijkheid voor betaalt, en daar gaat deze cursus over."}, {"t": "callout", "kind": "note", "title": "De ongemakkelijke versie", "text": "Als je enige vaardigheid het produceren van werkende code is, dan is die vaardigheid nu een commodity. Kun je bepalen wat er moet bestaan, een model daarheen sturen en het verschil zien tussen goed en net-werkend — dan heb je meer hefboom dan je ooit hebt gehad."}, {"t": "h", "text": "Genereren is niet het moeilijke deel"}, {"t": "p", "text": "Kijk mee met iemand die hier nieuw in is en je ziet steeds hetzelfde patroon. Ze vragen om een website. Ze krijgen er een. Hij ziet er aannemelijk uit. Ze vragen om een wijziging. Ze krijgen een ander aannemelijk ding, en iets wat eerst werkte, stopt stilletjes met werken. Twintig minuten later hebben ze een map met code die niemand begrijpt, zijzelf incluis."}, {"t": "p", "text": "Technisch ging er niets mis. Wat er misging, is dat niemand stuurde. Elke prompt was een nieuwe wens in plaats van een stap in een bouwproces."}, {"t": "demo", "kind": "context-compare", "title": "Dezelfde vraag, twee manieren"}, {"t": "h", "text": "Het mentale model dat werkt"}, {"t": "p", "text": "Behandel het model als een extreem snelle, extreem belezen collega die je project nooit heeft gezien, geen mening heeft over je klant, en precies doet wat je vraagt in plaats van wat je bedoelt. Die collega is oprecht waardevol. Hij vervangt niet dat jij weet wat je wilt."}, {"t": "list", "items": ["Jij bepaalt wat er gebouwd wordt. Het model stelt voor hoe.", "Jij geeft context. Zonder context krijg je het gemiddelde van alles wat het ooit gelezen heeft.", "Jij leest de output. Niet om hem te bewonderen — om hem te beoordelen.", "Jij bent eigenaar van het resultaat. Het model staat niet op de factuur."]}, {"t": "prompt", "n": "01", "title": "Een eerste prompt die zijn plek verdient", "body": "Ik leer AI-ondersteund webontwikkelen. Leg in gewone taal en in minder dan 200 woorden het verschil uit tussen wat een browser downloadt en wat een server doet. Ga ervan uit dat ik nooit code heb geschreven. Gebruik één concreet voorbeeld: iemand die de website van een bakker op zijn telefoon opent.", "why": {"context": "Het zegt wie je bent en wat je al weet, zodat het antwoord op jou is gericht en niet op niemand.", "constraints": "Minder dan 200 woorden, gewone taal, één voorbeeld. Elke beperking sluit een soort antwoord uit dat je niet wilde.", "output": "Een uitleg, geen code — precies de juiste output voor de vraag die gesteld wordt.", "iteration": "Raakt een zin je kwijt, citeer hem dan terug en vraag om alleen die zin opnieuw uit te leggen. Begin niet opnieuw."}}, {"t": "task", "title": "Probeer het voor de volgende les", "steps": ["Open Claude en voer de prompt hierboven ongewijzigd uit.", "Lees het antwoord en zoek de ene zin waar je het minst zeker over bent.", "Citeer die zin terug en vraag om een andere uitleg.", "Merk op hoeveel beter het tweede antwoord is — en dat de verbetering van jou kwam, niet van het model."], "done": "Je hebt een gesprek gevoerd in plaats van een verzoek gedaan. Dat onderscheid is de hele cursus."}, {"t": "quiz", "q": "Wat wordt goedkoper met AI-hulp, en wat niet?", "type": "single", "options": ["Alles wordt ongeveer even veel goedkoper", "Code produceren wordt veel goedkoper; bepalen wat je bouwt en kwaliteit beoordelen niet", "Alleen boilerplate wordt goedkoper; echte code verandert niet", "Er verandert niets, de tools zijn gewoon snellere autocomplete"], "correct": [1], "why": "Eerste versies en boilerplate storten in prijs in. Oordeel, smaak en verantwoordelijkheid bewegen geen millimeter — en precies daar zit je waarde nu."}, {"t": "summary", "points": ["Het werk verschoof van typen naar beslissen, sturen, lezen en beoordelen.", "Genereren is de goedkope helft. Sturen is de helft die geld waard is.", "Behandel het model als een snelle collega zonder context, niet als een orakel.", "Jij bent eigenaar van de output, dus je moet hem kunnen lezen."]}]'::jsonb, 1, true, 9, null, null),
  ('734623b4-31fc-5874-8621-dd1b7dcd5497', '0117796f-d1ee-5e5a-8132-f58c5592b527', 'how-websites-actually-work', 'How websites actually work', 'One request, three files, and a machine that does exactly what it is told.', '[{"t": "h", "text": "A website is a conversation between two machines."}, {"t": "p", "text": "Someone types an address. Their browser sends a request across the network. A server somewhere answers with a file. The browser reads that file, discovers it needs a few more, asks for those too, and then draws the result on screen. That is the entire mechanism. Everything else is detail."}, {"t": "figure", "kind": "request", "caption": "What happens between typing an address and seeing a page"}, {"t": "h", "text": "The browser is not clever, and that is good news"}, {"t": "p", "text": "A browser does not interpret your intentions. It reads instructions and follows them precisely. If your page looks wrong, the browser is not confused — it is doing exactly what your code says. This is the single most useful belief you can hold while debugging: **the machine is not being difficult, your instructions are.**"}, {"t": "p", "text": "Watch the order it works in. First it reads the HTML and builds a tree of elements. Then it applies the CSS to decide how each element looks and where it sits. Then it runs the JavaScript, which can change either of those. Then it paints. When something appears and then jumps, you have usually watched that sequence happen out of order."}, {"t": "code", "lang": "html", "filename": "index.html", "code": "<!DOCTYPE html>\n<html lang=\"en\">\n  <head>\n    <title>Vlaam Bakery</title>\n    <link rel=\"stylesheet\" href=\"styles.css\">\n  </head>\n  <body>\n    <h1>Bread, daily, from six.</h1>\n    <script src=\"script.js\"></script>\n  </body>\n</html>"}, {"t": "p", "text": "That file is a complete website. It is not a good one, but nothing is missing. The `<link>` tells the browser to go and fetch a second file. The `<script>` tells it to fetch a third. Three requests, one page."}, {"t": "callout", "kind": "tip", "title": "Open the Network panel once", "text": "Right-click any page, choose Inspect, open the Network tab and reload. Every row is one request. This is not an advanced tool — it is the honest picture of what a website is, and it takes ten seconds to look at."}, {"t": "h", "text": "Why this matters for prompting"}, {"t": "p", "text": "When you know a page is files fetched over a network, a lot of vague requests turn into precise ones. ''Make it load faster'' becomes ''reduce the number of requests and the size of the largest one''. ''It flashes when it loads'' becomes ''the CSS arrives after the first paint''. You cannot ask for what you cannot name."}, {"t": "figure", "kind": "layers", "caption": "The three layers, and what each one is responsible for"}, {"t": "prompt", "n": "02", "title": "Read your own page back", "body": "Here is my index.html:\n\n{PASTE FILE}\n\nWalk me through exactly what the browser does with this file, in order, from the moment it arrives. Say which additional files it will request and when. Point out anything that would delay the first paint. Do not suggest improvements yet — I want to understand the sequence first.", "why": {"context": "Your actual file, not a generic example, so the explanation is about your page.", "constraints": "''In order'' forces a sequence rather than a summary. ''No improvements yet'' keeps the answer explanatory.", "output": "A walkthrough you can check against the Network panel.", "iteration": "Once you understand the sequence, ask for the single change that would most improve first paint."}}, {"t": "task", "title": "Build the smallest possible website", "steps": ["Make a folder called `first-site`.", "Create `index.html` and paste the example above into it.", "Double-click the file. It opens in your browser. That is a website.", "Open the Network panel and reload. Count the failed requests — styles.css and script.js do not exist yet.", "Create both files, empty, and reload. The failures disappear."], "done": "You have seen a page request files, fail to find them, and then find them. Most confusing bugs are a version of this."}, {"t": "quiz", "q": "A page renders, then a moment later the fonts and colours snap into place. What does that tell you?", "type": "single", "options": ["The server is slow", "The browser painted before the stylesheet had arrived and been applied", "The JavaScript failed", "The images are too large"], "correct": [1], "why": "The browser paints what it has. If the stylesheet arrives after the first paint, you see the unstyled version first. Knowing the sequence turns a mysterious flicker into a specific, fixable cause."}, {"t": "summary", "points": ["A website is files requested over a network and drawn by a browser.", "The browser reads HTML, applies CSS, runs JavaScript, then paints — in that order.", "The machine follows instructions exactly; wrong output means wrong instructions.", "Naming the mechanism is what lets you ask a precise question about it."]}]'::jsonb, 'Hoe websites echt werken', 'Eén request, drie bestanden en een machine die precies doet wat je zegt.', '[{"t": "h", "text": "Een website is een gesprek tussen twee machines."}, {"t": "p", "text": "Iemand typt een adres. Zijn browser stuurt een request over het netwerk. Ergens antwoordt een server met een bestand. De browser leest dat bestand, ontdekt dat hij er nog een paar nodig heeft, vraagt die ook op, en tekent daarna het resultaat op het scherm. Dat is het hele mechanisme. De rest is detail."}, {"t": "figure", "kind": "request", "caption": "Wat er gebeurt tussen het typen van een adres en het zien van een pagina"}, {"t": "h", "text": "De browser is niet slim, en dat is goed nieuws"}, {"t": "p", "text": "Een browser interpreteert je bedoelingen niet. Hij leest instructies en volgt ze exact op. Ziet je pagina er verkeerd uit, dan is de browser niet in de war — hij doet precies wat je code zegt. Dit is de nuttigste overtuiging die je kunt hebben tijdens het debuggen: **de machine doet niet moeilijk, jouw instructies doen dat.**"}, {"t": "p", "text": "Let op de volgorde waarin hij werkt. Eerst leest hij de HTML en bouwt hij een boom van elementen. Daarna past hij de CSS toe om te bepalen hoe elk element eruitziet en waar het staat. Daarna draait hij de JavaScript, die beide kan veranderen. Daarna tekent hij. Als iets verschijnt en vervolgens verspringt, heb je die volgorde meestal door elkaar zien lopen."}, {"t": "code", "lang": "html", "filename": "index.html", "code": "<!DOCTYPE html>\n<html lang=\"en\">\n  <head>\n    <title>Vlaam Bakery</title>\n    <link rel=\"stylesheet\" href=\"styles.css\">\n  </head>\n  <body>\n    <h1>Bread, daily, from six.</h1>\n    <script src=\"script.js\"></script>\n  </body>\n</html>"}, {"t": "p", "text": "Dat bestand is een complete website. Geen goede, maar er ontbreekt niets. De `<link>` zegt de browser dat hij een tweede bestand moet ophalen. De `<script>` zegt hem een derde op te halen. Drie requests, één pagina."}, {"t": "callout", "kind": "tip", "title": "Open het Network-paneel één keer", "text": "Klik met rechts op een willekeurige pagina, kies Inspect, open het tabblad Network en herlaad. Elke regel is één request. Dit is geen gevorderd gereedschap — het is het eerlijke beeld van wat een website is, en je kijkt er in tien seconden naar."}, {"t": "h", "text": "Waarom dit uitmaakt voor prompten"}, {"t": "p", "text": "Als je weet dat een pagina bestanden zijn die over een netwerk worden opgehaald, worden veel vage verzoeken opeens precies. ''Maak het sneller'' wordt ''verlaag het aantal requests en de omvang van het grootste''. ''Het flikkert bij het laden'' wordt ''de CSS komt aan na de eerste paint''. Je kunt niet vragen om wat je niet kunt benoemen."}, {"t": "figure", "kind": "layers", "caption": "De drie lagen, en waar elke laag verantwoordelijk voor is"}, {"t": "prompt", "n": "02", "title": "Lees je eigen pagina terug", "body": "Dit is mijn index.html:\n\n{PASTE FILE}\n\nLoop precies met me door wat de browser met dit bestand doet, op volgorde, vanaf het moment dat het binnenkomt. Zeg welke extra bestanden hij opvraagt en wanneer. Wijs alles aan wat de eerste paint zou vertragen. Stel nog geen verbeteringen voor — ik wil eerst de volgorde begrijpen.", "why": {"context": "Jouw eigen bestand, geen algemeen voorbeeld, dus de uitleg gaat over jouw pagina.", "constraints": "''Op volgorde'' dwingt een reeks af in plaats van een samenvatting. ''Nog geen verbeteringen'' houdt het antwoord uitleggend.", "output": "Een doorloop die je kunt naleggen naast het Network-paneel.", "iteration": "Zodra je de volgorde begrijpt, vraag je om de ene wijziging die de eerste paint het meest verbetert."}}, {"t": "task", "title": "Bouw de kleinst mogelijke website", "steps": ["Maak een map met de naam `first-site`.", "Maak `index.html` en plak het voorbeeld hierboven erin.", "Dubbelklik op het bestand. Het opent in je browser. Dat is een website.", "Open het Network-paneel en herlaad. Tel de mislukte requests — styles.css en script.js bestaan nog niet.", "Maak beide bestanden aan, leeg, en herlaad. De fouten verdwijnen."], "done": "Je hebt een pagina bestanden zien opvragen, ze niet zien vinden, en ze daarna wel zien vinden. De meeste verwarrende bugs zijn een variant hiervan."}, {"t": "quiz", "q": "Een pagina verschijnt, en even later springen de fonts en kleuren op hun plek. Wat zegt dat je?", "type": "single", "options": ["De server is traag", "De browser heeft getekend voordat de stylesheet was aangekomen en toegepast", "De JavaScript is mislukt", "De afbeeldingen zijn te groot"], "correct": [1], "why": "De browser tekent wat hij heeft. Komt de stylesheet aan na de eerste paint, dan zie je eerst de ongestyleerde versie. Als je de volgorde kent, verandert een mysterieuze flikkering in een specifieke, oplosbare oorzaak."}, {"t": "summary", "points": ["Een website is bestanden die over een netwerk worden opgevraagd en door een browser getekend.", "De browser leest HTML, past CSS toe, draait JavaScript en tekent dan — in die volgorde.", "De machine volgt instructies exact; verkeerde output betekent verkeerde instructies.", "Het mechanisme benoemen is wat je in staat stelt er een precieze vraag over te stellen."]}]'::jsonb, 2, true, 11, null, null),
  ('a044bdc0-1547-528e-8935-8eb24968a3e7', '0117796f-d1ee-5e5a-8132-f58c5592b527', 'frontend-vs-backend', 'Frontend vs backend', 'Not a difficulty ranking. A question of whose computer it runs on.', '[{"t": "h", "text": "Whose computer is it running on?"}, {"t": "p", "text": "That is the whole distinction. Front end runs on the visitor''s device, inside their browser. Back end runs on a machine you control. People treat this as a seniority ladder — it is not. It is a boundary, and the boundary has consequences you need to feel in your bones."}, {"t": "figure", "kind": "split", "caption": "The boundary, and what it means for trust"}, {"t": "h", "text": "The consequence that matters"}, {"t": "p", "text": "Anything running on the visitor''s device is under the visitor''s control. They can read it, pause it, change it and lie to it. This is not a flaw to be patched — it is what a browser is. A person can open the developer tools right now and edit any page they are looking at."}, {"t": "p", "text": "So: a check that lives in the browser is a convenience, not a rule. Hiding an admin button stops nobody. Validating a form in the browser makes it pleasant to fill in; it does not make the data safe. **Every rule that actually matters has to be enforced on the server.**"}, {"t": "callout", "kind": "warning", "title": "The mistake that ends careers early", "text": "Never put a secret in code the browser downloads. Not an API key, not a password, not a database credential. If the browser can read it, so can everyone who visits your site — including the person who is looking for exactly that."}, {"t": "p", "text": "This course''s own platform is a working example. The interface hides the admin section from a student, because showing it would be confusing. But the actual protection is a rule on the database that refuses to return other people''s data to a student''s session, no matter what the browser asks for. The hidden button is manners. The database rule is security."}, {"t": "h", "text": "What lives where"}, {"t": "list", "items": ["**Front end** — layout, typography, interactions, animation, form usability, anything the visitor sees or touches.", "**Back end** — accounts and passwords, permissions, saved data, payments, anything that must be true regardless of what the browser claims.", "**Both, deliberately** — validation. Check in the browser so the form is pleasant. Check again on the server because that is the check that counts."]}, {"t": "demo", "kind": "trust-boundary", "title": "Which side does this belong on?"}, {"t": "prompt", "n": "03", "title": "Ask where a rule belongs", "body": "I am building {FEATURE}. List every rule that has to be true for it to work correctly.\n\nFor each rule, tell me whether it must be enforced on the server, whether it should also be checked in the browser for usability, and what an attacker could do if it were only checked in the browser.\n\nBe blunt about the consequences. I would rather be uncomfortable now.", "why": {"context": "Naming the feature lets the model infer rules you have not thought of.", "constraints": "Forcing a server/browser answer per rule prevents a vague ''validate both sides'' response.", "output": "A table of decisions plus the consequence of getting each one wrong.", "iteration": "Take the highest-consequence rule and ask how to enforce it on the server in your stack."}}, {"t": "task", "title": "Break a page on purpose", "steps": ["Open any site with a form that has a disabled submit button.", "Right-click the button and choose Inspect.", "Delete the `disabled` attribute in the elements panel.", "The button is now clickable. You changed their page — on your machine only.", "Sit with what that means for every check written in the browser."], "done": "You have felt the trust boundary rather than read about it. That feeling is what stops you writing an insecure feature later."}, {"t": "quiz", "q": "Your app hides the ''Delete user'' button unless the logged-in account is an admin. Is that sufficient?", "type": "single", "options": ["Yes — a student cannot see the button, so they cannot use it", "No — the browser can be edited, so the server must refuse the request as well", "Yes, provided the button is removed rather than hidden with CSS", "It depends on whether the site uses HTTPS"], "correct": [1], "why": "Hiding a control is user experience. The delete endpoint itself has to check who is asking and refuse anyone who is not an admin — that check is the security. HTTPS protects the message in transit; it says nothing about who is allowed to send it."}, {"t": "summary", "points": ["Front end runs on their computer, back end on yours. That is the whole definition.", "Anything the browser receives, the visitor can read and change.", "Browser checks are for usability. Server checks are for correctness and safety.", "Never put a secret in front-end code."]}]'::jsonb, 'Front-end vs back-end', 'Geen moeilijkheidsranglijst. Een kwestie van op wiens computer het draait.', '[{"t": "h", "text": "Op wiens computer draait het?"}, {"t": "p", "text": "Dat is het hele onderscheid. Front-end draait op het apparaat van de bezoeker, in zijn browser. Back-end draait op een machine die jij beheert. Mensen behandelen dit als een senioriteitsladder — dat is het niet. Het is een grens, en die grens heeft gevolgen die je in je botten moet voelen."}, {"t": "figure", "kind": "split", "caption": "De grens, en wat die betekent voor vertrouwen"}, {"t": "h", "text": "Het gevolg dat ertoe doet"}, {"t": "p", "text": "Alles wat op het apparaat van de bezoeker draait, staat onder controle van die bezoeker. Hij kan het lezen, pauzeren, aanpassen en ertegen liegen. Dit is geen fout die je dichttimmert — dit is wat een browser is. Iemand kan nu meteen de developer tools openen en elke pagina aanpassen waar hij naar kijkt."}, {"t": "p", "text": "Dus: een controle die in de browser leeft, is een gemak, geen regel. Een adminknop verbergen houdt niemand tegen. Een formulier in de browser valideren maakt het prettig invullen; het maakt de data niet veilig. **Elke regel die er echt toe doet, moet op de server worden afgedwongen.**"}, {"t": "callout", "kind": "warning", "title": "De fout die carrières vroeg beëindigt", "text": "Zet nooit een geheim in code die de browser downloadt. Geen API-sleutel, geen wachtwoord, geen databasegegevens. Als de browser het kan lezen, kan iedereen die je site bezoekt dat ook — inclusief degene die precies daarnaar op zoek is."}, {"t": "p", "text": "Het platform van deze cursus is zelf een werkend voorbeeld. De interface verbergt het admingedeelte voor een cursist, omdat het tonen ervan verwarrend zou zijn. Maar de echte bescherming is een regel op de database die weigert om andermans data terug te geven aan de sessie van een cursist, wat de browser ook vraagt. De verborgen knop is beleefdheid. De databaseregel is beveiliging."}, {"t": "h", "text": "Wat waar hoort"}, {"t": "list", "items": ["**Front-end** — layout, typografie, interacties, animatie, bruikbaarheid van formulieren, alles wat de bezoeker ziet of aanraakt.", "**Back-end** — accounts en wachtwoorden, rechten, opgeslagen data, betalingen, alles wat waar moet zijn ongeacht wat de browser beweert.", "**Allebei, bewust** — validatie. Controleer in de browser zodat het formulier prettig werkt. Controleer opnieuw op de server, want dat is de controle die telt."]}, {"t": "demo", "kind": "trust-boundary", "title": "Aan welke kant hoort dit?"}, {"t": "prompt", "n": "03", "title": "Vraag waar een regel hoort", "body": "Ik bouw {FEATURE}. Noem elke regel die waar moet zijn om het correct te laten werken.\n\nZeg per regel of die op de server afgedwongen moet worden, of die ook in de browser gecontroleerd zou moeten worden voor de bruikbaarheid, en wat een aanvaller zou kunnen doen als de controle alleen in de browser zat.\n\nWees bot over de gevolgen. Ik voel me nu liever ongemakkelijk.", "why": {"context": "Door de functie te benoemen kan het model regels afleiden waar jij niet aan gedacht hebt.", "constraints": "Per regel een antwoord server/browser afdwingen voorkomt een vaag ''valideer aan beide kanten''.", "output": "Een tabel met beslissingen plus het gevolg van elke keer dat je er een verkeerd neemt.", "iteration": "Neem de regel met de zwaarste gevolgen en vraag hoe je die op de server afdwingt in jouw stack."}}, {"t": "task", "title": "Breek een pagina met opzet", "steps": ["Open een willekeurige site met een formulier waarvan de verzendknop uitgeschakeld is.", "Klik met rechts op de knop en kies Inspect.", "Verwijder het `disabled`-attribuut in het elements-paneel.", "De knop is nu klikbaar. Je hebt hun pagina veranderd — alleen op jouw machine.", "Laat even bezinken wat dat betekent voor elke controle die in de browser staat."], "done": "Je hebt de vertrouwensgrens gevoeld in plaats van erover gelezen. Dat gevoel is wat je er later van weerhoudt om een onveilige functie te bouwen."}, {"t": "quiz", "q": "Je app verbergt de knop ''Gebruiker verwijderen'' tenzij het ingelogde account een admin is. Is dat genoeg?", "type": "single", "options": ["Ja — een cursist ziet de knop niet, dus kan hij hem niet gebruiken", "Nee — de browser is aan te passen, dus de server moet het verzoek ook weigeren", "Ja, mits de knop verwijderd wordt in plaats van verborgen met CSS", "Het hangt ervan af of de site HTTPS gebruikt"], "correct": [1], "why": "Een knop verbergen is gebruikerservaring. Het verwijder-endpoint moet zelf controleren wie het vraagt en iedereen weigeren die geen admin is — die controle is de beveiliging. HTTPS beschermt het bericht onderweg; het zegt niets over wie het mag versturen."}, {"t": "summary", "points": ["Front-end draait op hun computer, back-end op die van jou. Dat is de hele definitie.", "Alles wat de browser binnenkrijgt, kan de bezoeker lezen en veranderen.", "Controles in de browser zijn voor bruikbaarheid. Controles op de server zijn voor correctheid en veiligheid.", "Zet nooit een geheim in front-end code."]}]'::jsonb, 3, true, 10, null, null),
  ('8c66b0a1-6fa3-53db-8fde-4f411b2e0507', '0117796f-d1ee-5e5a-8132-f58c5592b527', 'html-css-javascript', 'HTML, CSS & JavaScript', 'Structure, appearance and behaviour — and why keeping them separate makes AI output far easier to fix.', '[{"t": "h", "text": "Three languages, three jobs."}, {"t": "p", "text": "HTML says what things *are*. CSS says how they *look*. JavaScript says how they *behave*. That separation is not academic tidiness — it is what lets you change one thing without breaking the other two, and it is the first thing to check when generated code becomes hard to work with."}, {"t": "figure", "kind": "layers", "caption": "Same content, three layers of responsibility"}, {"t": "h", "text": "HTML: meaning, not appearance"}, {"t": "p", "text": "Choosing `<button>` instead of `<div>` is not pedantry. A real button is focusable by keyboard, announces itself to a screen reader, and responds to the space bar — for free, because you used the right element. A `<div>` styled to look like a button has none of that until you rebuild it by hand, badly."}, {"t": "code", "lang": "html", "filename": "index.html", "code": "<!-- meaning is visible in the markup -->\n<article class=\"card\">\n  <h2>Sourdough</h2>\n  <p>Twenty-four hour ferment. Out at six.</p>\n  <button type=\"button\">Reserve a loaf</button>\n</article>"}, {"t": "p", "text": "Read that without any CSS and you still know what it is. That is the test. If you have to look at the stylesheet to work out what a piece of markup means, the markup is wrong."}, {"t": "h", "text": "CSS: a system, not a pile of rules"}, {"t": "p", "text": "Most generated CSS works and is still bad, for one reason: it repeats itself. A colour written in eleven places is eleven places to change. Custom properties fix this, and asking for them changes the quality of everything the model gives you afterwards."}, {"t": "code", "lang": "css", "filename": "styles.css", "code": ":root{\n  --ink: #0d0d0d;\n  --paper: #ffffff;\n  --accent: #c6ff4a;\n  --space: 8px;\n  --radius: 24px;\n}\n\n.card{\n  background: var(--paper);\n  border-radius: var(--radius);\n  padding: calc(var(--space) * 3);\n  color: var(--ink);\n}"}, {"t": "demo", "kind": "code-explainer", "title": "Change a value, watch the design move"}, {"t": "h", "text": "JavaScript: behaviour, added last"}, {"t": "p", "text": "The useful discipline is to build the page so it makes sense without JavaScript, then add behaviour on top. Not because visitors disable it, but because a page that depends on script for its basic meaning is a page that breaks completely when one line fails."}, {"t": "code", "lang": "js", "filename": "script.js", "code": "const button = document.querySelector(''.card button'');\n\nbutton?.addEventListener(''click'', () => {\n  button.textContent = ''Reserved'';\n  button.disabled = true;\n});"}, {"t": "callout", "kind": "tip", "title": "The `?.` is not decoration", "text": "If `querySelector` finds nothing it returns `null`, and calling a method on `null` throws an error that stops every line of script after it. The `?.` says ''only if this exists''. One character, and the rest of your page keeps working."}, {"t": "prompt", "n": "04", "title": "Ask for the three layers to stay separate", "body": "Build a {COMPONENT} using plain HTML, CSS and JavaScript in three separate files.\n\nRules:\n- HTML carries meaning only. Use semantic elements. No styling attributes, no presentational class names like `red-text`.\n- All colours, spacing and radii come from CSS custom properties defined once on :root.\n- JavaScript adds behaviour only. The component must still make sense with JavaScript switched off.\n\nAfter the code, list which decisions you made that I might reasonably disagree with.", "why": {"context": "Three files, named layers — the model now has an architecture to work inside.", "constraints": "Each rule removes a specific bad habit: inline styles, magic values, script-dependent meaning.", "output": "Code plus a list of debatable choices, which turns a delivery into a conversation.", "iteration": "Argue with one item on that list. That exchange is where you learn the most."}}, {"t": "task", "title": "Take the layers apart", "steps": ["Ask Claude for a pricing card with the prompt above.", "Save the three files and open the page.", "Comment out the `<link>` to the stylesheet and reload. Can you still tell what everything is?", "Restore it, then comment out the `<script>`. Is the card still readable?", "If either answer is no, tell Claude which one and ask it to fix that specific failure."], "done": "You have tested the separation instead of trusting it. This is the fastest way to find out whether generated code is actually well built."}, {"t": "quiz", "q": "Why prefer `<button>` over a `<div>` with a click handler?", "type": "multi", "options": ["It is reachable and operable by keyboard without extra code", "Screen readers announce it as a button", "It responds to Enter and Space by default", "It renders faster"], "correct": [0, 1, 2], "why": "Focusability, the announced role and keyboard activation all come free with the correct element. Rendering speed is not the reason — accessibility and less code you have to write and maintain are."}, {"t": "summary", "points": ["HTML is meaning, CSS is appearance, JavaScript is behaviour.", "Markup should be readable with no stylesheet attached.", "Define colours and spacing once as custom properties, then reuse them.", "Add behaviour last, and make sure the page survives without it."]}]'::jsonb, 'HTML, CSS & JavaScript', 'Structuur, uiterlijk en gedrag — en waarom je AI-output veel makkelijker repareert als je ze gescheiden houdt.', '[{"t": "h", "text": "Drie talen, drie taken."}, {"t": "p", "text": "HTML zegt wat dingen *zijn*. CSS zegt hoe ze *eruitzien*. JavaScript zegt hoe ze zich *gedragen*. Die scheiding is geen academische netheid — ze zorgt dat je het ene kunt veranderen zonder de andere twee te breken, en ze is het eerste wat je controleert als gegenereerde code lastig werkbaar wordt."}, {"t": "figure", "kind": "layers", "caption": "Dezelfde inhoud, drie lagen verantwoordelijkheid"}, {"t": "h", "text": "HTML: betekenis, geen uiterlijk"}, {"t": "p", "text": "Kiezen voor `<button>` in plaats van `<div>` is geen muggenzifterij. Een echte knop krijgt focus met het toetsenbord, meldt zichzelf aan een schermlezer en reageert op de spatiebalk — gratis, omdat je het juiste element gebruikte. Een `<div>` die is opgemaakt als knop heeft daar niets van, totdat je het met de hand nabouwt, slecht."}, {"t": "code", "lang": "html", "filename": "index.html", "code": "<!-- meaning is visible in the markup -->\n<article class=\"card\">\n  <h2>Sourdough</h2>\n  <p>Twenty-four hour ferment. Out at six.</p>\n  <button type=\"button\">Reserve a loaf</button>\n</article>"}, {"t": "p", "text": "Lees dat zonder CSS en je weet nog steeds wat het is. Dat is de toets. Moet je de stylesheet erbij pakken om te snappen wat een stuk markup betekent, dan klopt de markup niet."}, {"t": "h", "text": "CSS: een systeem, geen stapel regels"}, {"t": "p", "text": "De meeste gegenereerde CSS werkt en is toch slecht, om één reden: ze herhaalt zichzelf. Een kleur die op elf plekken staat, is elf plekken om aan te passen. Custom properties lossen dat op, en erom vragen verandert de kwaliteit van alles wat het model je daarna geeft."}, {"t": "code", "lang": "css", "filename": "styles.css", "code": ":root{\n  --ink: #0d0d0d;\n  --paper: #ffffff;\n  --accent: #c6ff4a;\n  --space: 8px;\n  --radius: 24px;\n}\n\n.card{\n  background: var(--paper);\n  border-radius: var(--radius);\n  padding: calc(var(--space) * 3);\n  color: var(--ink);\n}"}, {"t": "demo", "kind": "code-explainer", "title": "Verander één waarde, zie het ontwerp meebewegen"}, {"t": "h", "text": "JavaScript: gedrag, als laatste toegevoegd"}, {"t": "p", "text": "De nuttige discipline is de pagina zo bouwen dat ze klopt zonder JavaScript, en het gedrag er daarna bovenop leggen. Niet omdat bezoekers het uitzetten, maar omdat een pagina die voor haar basisbetekenis van script afhangt, volledig stukgaat zodra één regel faalt."}, {"t": "code", "lang": "js", "filename": "script.js", "code": "const button = document.querySelector(''.card button'');\n\nbutton?.addEventListener(''click'', () => {\n  button.textContent = ''Reserved'';\n  button.disabled = true;\n});"}, {"t": "callout", "kind": "tip", "title": "De `?.` is geen versiering", "text": "Vindt `querySelector` niets, dan geeft hij `null` terug, en een methode aanroepen op `null` gooit een fout die elke regel script daarna stopzet. De `?.` zegt ''alleen als dit bestaat''. Eén teken, en de rest van je pagina blijft werken."}, {"t": "prompt", "n": "04", "title": "Vraag om drie lagen die gescheiden blijven", "body": "Bouw een {COMPONENT} met gewone HTML, CSS en JavaScript in drie aparte bestanden.\n\nRegels:\n- HTML draagt alleen betekenis. Gebruik semantische elementen. Geen opmaakattributen, geen presentatieve klassenamen zoals `red-text`.\n- Alle kleuren, ruimtes en radii komen uit CSS custom properties die één keer op :root zijn gedefinieerd.\n- JavaScript voegt alleen gedrag toe. Het component moet ook kloppen met JavaScript uitgeschakeld.\n\nNoem na de code welke beslissingen je hebt genomen waar ik het redelijkerwijs niet mee eens zou kunnen zijn.", "why": {"context": "Drie bestanden, benoemde lagen — het model heeft nu een architectuur om binnen te werken.", "constraints": "Elke regel haalt een specifieke slechte gewoonte weg: inline styles, magische waarden, betekenis die van script afhangt.", "output": "Code plus een lijst met betwistbare keuzes, waarmee een oplevering een gesprek wordt.", "iteration": "Ga met één punt op die lijst in discussie. In die uitwisseling leer je het meest."}}, {"t": "task", "title": "Haal de lagen uit elkaar", "steps": ["Vraag Claude om een prijskaart met de prompt hierboven.", "Sla de drie bestanden op en open de pagina.", "Zet de `<link>` naar de stylesheet in commentaar en herlaad. Kun je nog steeds zien wat alles is?", "Zet hem terug en zet daarna de `<script>` in commentaar. Is de kaart nog leesbaar?", "Is een van beide antwoorden nee, zeg Claude welke en vraag om precies dat probleem op te lossen."], "done": "Je hebt de scheiding getest in plaats van erop vertrouwd. Dit is de snelste manier om erachter te komen of gegenereerde code echt goed in elkaar zit."}, {"t": "quiz", "q": "Waarom `<button>` verkiezen boven een `<div>` met een click handler?", "type": "multi", "options": ["Hij is bereikbaar en bedienbaar met het toetsenbord zonder extra code", "Schermlezers kondigen hem aan als knop", "Hij reageert standaard op Enter en spatie", "Hij rendert sneller"], "correct": [0, 1, 2], "why": "Focus krijgen, de aangekondigde rol en bediening met het toetsenbord komen allemaal gratis met het juiste element. Rendersnelheid is niet de reden — toegankelijkheid en minder code die je moet schrijven en onderhouden wel."}, {"t": "summary", "points": ["HTML is betekenis, CSS is uiterlijk, JavaScript is gedrag.", "Markup hoort leesbaar te zijn zonder stylesheet.", "Definieer kleuren en ruimtes één keer als custom properties en hergebruik ze.", "Voeg gedrag als laatste toe, en zorg dat de pagina het zonder overleeft."]}]'::jsonb, 4, true, 14, null, null),
  ('8e6050cc-05cb-581d-b1ee-d8607fec7650', '0117796f-d1ee-5e5a-8132-f58c5592b527', 'what-claude-can-and-cannot-do', 'What Claude can and cannot do', 'An honest map of the tool, so you stop being surprised by it.', '[{"t": "h", "text": "Knowing the edges is what makes it useful."}, {"t": "p", "text": "Most frustration with AI coding comes from expecting the wrong thing. Not because the tool is bad, but because nobody drew the map. So here is the map, honestly, including the parts that are inconvenient."}, {"t": "h", "text": "What it genuinely does well"}, {"t": "list", "items": ["**First drafts of anything structured.** Layouts, components, forms, config files. Minutes instead of hours.", "**Explaining code you did not write.** Line by line, at whatever level you ask for.", "**Translating between languages and frameworks.** Same idea, different syntax.", "**Finding the cause of an error you can describe.** Give it the message and the code and it is usually right.", "**Boring correctness.** Accessibility attributes, responsive breakpoints, edge cases — provided you ask."]}, {"t": "h", "text": "What it cannot do, and will not tell you it cannot"}, {"t": "list", "items": ["**Know your context.** It has never met your client and cannot see your files unless you show it.", "**Remember yesterday.** A new conversation starts empty. Every time.", "**Have taste on your behalf.** It will produce something defensible. Whether it is *right* is your call.", "**See your screen.** ''It looks wrong'' is not a description it can act on.", "**Be certain.** It can be fluent and mistaken at the same time, with no change in tone."]}, {"t": "callout", "kind": "warning", "title": "Fluent and wrong look identical", "text": "This is the failure mode to internalise. Wrong answers arrive with exactly the same confidence as right ones. There is no tell. The only defence is to check — run it, read it, test the edge case."}, {"t": "figure", "kind": "context", "caption": "What the model can see when you ask it something"}, {"t": "h", "text": "Context is the whole game"}, {"t": "p", "text": "The model''s world is what is in the current conversation. Not your repository, not last week, not the thing you meant. If you have not said it, it does not exist. This sounds limiting until you realise it is completely under your control — which makes it a skill rather than an obstacle."}, {"t": "demo", "kind": "context-compare", "title": "Same question, different amounts of context"}, {"t": "h", "text": "How to work with the uncertainty"}, {"t": "p", "text": "You do not need to verify every line. You need a habit that catches the expensive mistakes: run it before you believe it, read anything that touches data or permissions, and ask ''what would make this wrong?'' whenever an answer arrives suspiciously neatly."}, {"t": "prompt", "n": "05", "title": "Make the model argue with itself", "body": "Here is a solution you just gave me:\n\n{PASTE}\n\nNow argue against it. What are its weaknesses? Where would it break — unusual input, small screens, slow connections, someone using only a keyboard? What did you assume that I never told you?\n\nBe specific and do not soften it.", "why": {"context": "Its own output, so the critique is concrete rather than general advice.", "constraints": "Named failure categories stop the answer being a shrug about edge cases.", "output": "A list of weaknesses and — most valuable — the assumptions it silently made.", "iteration": "Every assumption it names is a decision you never made. Make it now, explicitly."}}, {"t": "task", "title": "Catch a confident mistake", "steps": ["Ask Claude for a function that validates an email address with a regular expression.", "Before running it, ask: ''What valid addresses does this reject, and what invalid ones does it accept?''", "Read the answer. It will find real problems in its own code.", "Ask why it wrote the imperfect version first."], "done": "You have seen fluent output that was not complete, and you found it by asking rather than by luck."}, {"t": "quiz", "q": "Which of these is a genuine limitation rather than a prompting problem?", "type": "single", "options": ["It produced generic output", "It forgot a constraint from earlier in the conversation", "It cannot know whether your client will like the design", "It used a library you did not want"], "correct": [2], "why": "The other three are fixable by prompting better: add constraints, restate them, exclude the library. Whether a specific person likes a specific design is information the model does not have and cannot obtain."}, {"t": "summary", "points": ["Excellent at first drafts, explanation, translation and diagnosable errors.", "Cannot know your context, remember past sessions, or hold taste for you.", "Fluent and wrong are indistinguishable — check, do not trust.", "Context is the whole game, and it is entirely yours to control."]}]'::jsonb, 'Wat Claude wel en niet kan', 'Een eerlijke kaart van het gereedschap, zodat het je niet meer verrast.', '[{"t": "h", "text": "De randen kennen is wat het bruikbaar maakt."}, {"t": "p", "text": "De meeste frustratie met AI en code komt voort uit het verkeerde verwachten. Niet omdat het gereedschap slecht is, maar omdat niemand de kaart tekende. Dus hier is de kaart, eerlijk, inclusief de onhandige delen."}, {"t": "h", "text": "Wat het echt goed doet"}, {"t": "list", "items": ["**Eerste versies van alles wat structuur heeft.** Layouts, componenten, formulieren, configuratiebestanden. Minuten in plaats van uren.", "**Code uitleggen die je niet zelf schreef.** Regel voor regel, op het niveau dat je vraagt.", "**Vertalen tussen talen en frameworks.** Hetzelfde idee, andere syntaxis.", "**De oorzaak vinden van een fout die je kunt beschrijven.** Geef de melding en de code en het zit meestal goed.", "**Saaie correctheid.** Toegankelijkheidsattributen, responsive breakpoints, randgevallen — mits je erom vraagt."]}, {"t": "h", "text": "Wat het niet kan, en niet zal zeggen dat het niet kan"}, {"t": "list", "items": ["**Jouw context kennen.** Het heeft je klant nooit ontmoet en ziet je bestanden niet tenzij je ze laat zien.", "**Zich gisteren herinneren.** Een nieuw gesprek begint leeg. Elke keer.", "**Smaak hebben namens jou.** Het levert iets verdedigbaars. Of het *juist* is, bepaal jij.", "**Je scherm zien.** ''Het ziet er verkeerd uit'' is geen beschrijving waar het iets mee kan.", "**Zeker zijn.** Het kan tegelijk vloeiend en fout zijn, zonder dat de toon verandert."]}, {"t": "callout", "kind": "warning", "title": "Vloeiend en fout zien er identiek uit", "text": "Dit is de faalmodus die je je eigen moet maken. Foute antwoorden komen met precies hetzelfde zelfvertrouwen als goede. Er is geen signaal. De enige verdediging is controleren — draai het, lees het, test het randgeval."}, {"t": "figure", "kind": "context", "caption": "Wat het model kan zien als je het iets vraagt"}, {"t": "h", "text": "Context is het hele spel"}, {"t": "p", "text": "De wereld van het model is wat er in het huidige gesprek staat. Niet je repository, niet vorige week, niet wat je bedoelde. Wat je niet gezegd hebt, bestaat niet. Dat klinkt beperkend tot je beseft dat het volledig onder jouw controle staat — waarmee het een vaardigheid wordt in plaats van een obstakel."}, {"t": "demo", "kind": "context-compare", "title": "Dezelfde vraag, verschillende hoeveelheden context"}, {"t": "h", "text": "Hoe je met de onzekerheid omgaat"}, {"t": "p", "text": "Je hoeft niet elke regel te verifiëren. Je hebt een gewoonte nodig die de dure fouten vangt: draai het voordat je het gelooft, lees alles wat data of rechten raakt, en vraag ''wat zou dit fout maken?'' zodra een antwoord verdacht netjes binnenkomt."}, {"t": "prompt", "n": "05", "title": "Laat het model met zichzelf in discussie gaan", "body": "Dit is een oplossing die je me net gaf:\n\n{PASTE}\n\nBeargumenteer nu waarom hij niet deugt. Wat zijn de zwakke plekken? Waar gaat hij stuk — ongewone invoer, kleine schermen, trage verbindingen, iemand die alleen een toetsenbord gebruikt? Wat heb je aangenomen wat ik je nooit verteld heb?\n\nWees specifiek en verzacht het niet.", "why": {"context": "Zijn eigen output, dus de kritiek is concreet in plaats van algemeen advies.", "constraints": "Benoemde faalcategorieën voorkomen dat het antwoord een schouderophalen over randgevallen wordt.", "output": "Een lijst met zwakke plekken en — het waardevolst — de aannames die het stilzwijgend deed.", "iteration": "Elke aanname die het noemt, is een beslissing die jij nooit nam. Neem hem nu, expliciet."}}, {"t": "task", "title": "Betrap een zelfverzekerde fout", "steps": ["Vraag Claude om een functie die een e-mailadres valideert met een reguliere expressie.", "Vraag voordat je hem draait: ''Welke geldige adressen wijst dit af, en welke ongeldige laat het door?''", "Lees het antwoord. Het vindt echte problemen in zijn eigen code.", "Vraag waarom het eerst de imperfecte versie schreef."], "done": "Je hebt vloeiende output gezien die niet compleet was, en je vond het door te vragen, niet door geluk."}, {"t": "quiz", "q": "Wat hiervan is een echte beperking en geen promptprobleem?", "type": "single", "options": ["Het leverde generieke output", "Het vergat een beperking van eerder in het gesprek", "Het kan niet weten of je klant het ontwerp mooi vindt", "Het gebruikte een library die je niet wilde"], "correct": [2], "why": "De andere drie los je op met beter prompten: voeg beperkingen toe, herhaal ze, sluit de library uit. Of een specifiek persoon een specifiek ontwerp mooi vindt, is informatie die het model niet heeft en niet kan krijgen."}, {"t": "summary", "points": ["Uitstekend in eerste versies, uitleg, vertaling en diagnosticeerbare fouten.", "Kan jouw context niet kennen, eerdere sessies niet onthouden en geen smaak voor je hebben.", "Vloeiend en fout zijn niet te onderscheiden — controleer, vertrouw niet.", "Context is het hele spel, en die heb jij volledig in de hand."]}]'::jsonb, 5, true, 11, null, null),
  ('ec668ebf-8dd7-5a53-8a12-7e70c41b1e6a', '0117796f-d1ee-5e5a-8132-f58c5592b527', 'your-ai-development-workflow', 'Your AI development workflow', 'Thirteen steps you will use on every project for the rest of the course.', '[{"t": "h", "text": "A workflow beats a good prompt."}, {"t": "p", "text": "People chase the perfect prompt. The people who actually ship have something duller and far more effective: an order they always work in. It stops the two failures that ruin AI-assisted builds — starting to code before you know what you are building, and accepting output before you have checked it."}, {"t": "figure", "kind": "workflow", "caption": "The thirteen steps, and where each kind of prompt belongs"}, {"t": "h", "text": "The thirteen steps"}, {"t": "list", "ordered": true, "items": ["**Describe the goal.** One sentence. What must this thing do?", "**Give context.** Who is it for, what exists already, what is it part of?", "**Define constraints.** What is ruled out. This is where quality is decided.", "**Give visual direction.** Specific enough to be checkable, not ''modern and clean''.", "**Define technical requirements.** Files, dependencies, browser support, performance.", "**Ask for implementation.** Only now. Scoped to one piece.", "**Inspect the output.** Read it. Understand it. Do not skim it.", "**Test.** Run it. Resize it. Use the keyboard. Open the console.", "**Report problems.** Precisely: expected, actual, when it started.", "**Iterate.** Small, named changes. Keep what works.", "**Refactor.** Remove repetition once the shape has settled.", "**Polish.** Spacing, motion, states, the last ten per cent.", "**Ship.** Deploy, then check it again in public."]}, {"t": "callout", "kind": "note", "title": "Steps 1–5 are where the money is", "text": "Beginners start at step 6 and wonder why the result is generic. The first five steps cost ten minutes and determine everything the model produces afterwards. Skipping them does not save time; it moves the time to step 10, where it costs more."}, {"t": "h", "text": "What a real session looks like"}, {"t": "p", "text": "Not one prompt and a finished site. A conversation that narrows."}, {"t": "demo", "kind": "session", "title": "A real session, replayed"}, {"t": "p", "text": "Notice what happens there. The first exchange produces no code at all — it produces agreement about what is being built. The build then arrives in pieces small enough to judge. When something is wrong, the report is specific, so the fix is specific. Nothing gets rewritten from scratch, so nothing that worked quietly stops working."}, {"t": "h", "text": "Where it goes wrong"}, {"t": "list", "items": ["**Asking for everything at once.** You cannot review a whole site in one read, so you do not review it.", "**Vague problem reports.** ''It''s broken'' gets a guess. ''The nav overlaps the hero below 480px'' gets a fix.", "**Rewriting instead of adjusting.** Every rewrite reintroduces problems you had already solved.", "**Believing it because it compiles.** Working and correct are different words."]}, {"t": "prompt", "n": "06", "title": "Open a session properly", "body": "We are going to build {PROJECT} together over several messages. Before any code, confirm you have understood the following, and ask me about anything that is unclear or missing.\n\nGoal: {ONE SENTENCE}\nAudience: {WHO}\nOne action they should take: {ACTION}\nHard constraints: {LIST}\nVisual direction: {LIST}\nTechnical: plain HTML, CSS and JavaScript in three files, no libraries, must work from 360px up.\n\nThen propose a build order — which piece we should make first, and why.", "why": {"context": "Everything the model needs, in one place, at the start of the session.", "constraints": "Stated once here rather than repeated in every later message.", "output": "Confirmation, questions and a build order — no code until the plan is agreed.", "iteration": "Its questions are the gaps in your own thinking. Answer them properly; that is the real value of this step."}}, {"t": "task", "title": "Run the workflow once, end to end", "steps": ["Pick something genuinely small: a single contact section.", "Write out steps 1 to 5 in a text file before you open Claude.", "Send the opening prompt above and answer whatever it asks.", "Ask for the implementation. Read every line before you run it.", "Test it at 360px and with the keyboard only. Report one problem precisely.", "Iterate until it is right. Note how many messages it took."], "done": "You have completed one full loop. Every project in this course is this loop, repeated at a larger size."}, {"t": "quiz", "q": "Where do most AI-assisted builds actually go wrong?", "type": "single", "options": ["The model produces poor code", "The developer starts at step 6 and skips goal, context and constraints", "The technology is not mature enough", "There are not enough good prompt templates available"], "correct": [1], "why": "The code is usually fine for what was asked. What is missing is the five steps before the asking — which is why the same model produces mediocre work for one person and excellent work for another."}, {"t": "summary", "points": ["A repeatable order beats a clever prompt.", "Steps 1 to 5 happen before any code exists, and decide the outcome.", "Build in pieces small enough to actually review.", "Report problems precisely; adjust rather than rewrite."]}]'::jsonb, 'Jouw AI-ontwikkelworkflow', 'Dertien stappen die je in elk project gebruikt, de rest van de cursus lang.', '[{"t": "h", "text": "Een workflow verslaat een goede prompt."}, {"t": "p", "text": "Mensen jagen op de perfecte prompt. De mensen die daadwerkelijk opleveren, hebben iets saaiers en veel effectievers: een volgorde waarin ze altijd werken. Die voorkomt de twee fouten die AI-ondersteunde builds verpesten — beginnen met coderen voordat je weet wat je bouwt, en output accepteren voordat je hem gecontroleerd hebt."}, {"t": "figure", "kind": "workflow", "caption": "De dertien stappen, en waar elk soort prompt thuishoort"}, {"t": "h", "text": "De dertien stappen"}, {"t": "list", "ordered": true, "items": ["**Beschrijf het doel.** Eén zin. Wat moet dit ding doen?", "**Geef context.** Voor wie is het, wat bestaat er al, waar is het onderdeel van?", "**Bepaal de beperkingen.** Wat valt af. Hier wordt de kwaliteit beslist.", "**Geef visuele richting.** Specifiek genoeg om te controleren, niet ''modern en clean''.", "**Bepaal de technische eisen.** Bestanden, dependencies, browserondersteuning, performance.", "**Vraag om implementatie.** Pas nu. Afgebakend tot één onderdeel.", "**Bekijk de output.** Lees hem. Begrijp hem. Scan hem niet.", "**Test.** Draai het. Verander de breedte. Gebruik het toetsenbord. Open de console.", "**Meld problemen.** Precies: verwacht, werkelijk, wanneer het begon.", "**Itereer.** Kleine, benoemde wijzigingen. Houd wat werkt.", "**Refactor.** Haal herhaling weg zodra de vorm is uitgekristalliseerd.", "**Polijst.** Ruimte, beweging, states, de laatste tien procent.", "**Lever op.** Deploy, en controleer het daarna nog eens in het openbaar."]}, {"t": "callout", "kind": "note", "title": "In stap 1–5 zit het geld", "text": "Beginners starten bij stap 6 en vragen zich af waarom het resultaat generiek is. De eerste vijf stappen kosten tien minuten en bepalen alles wat het model daarna produceert. Ze overslaan bespaart geen tijd; het verplaatst de tijd naar stap 10, waar hij duurder is."}, {"t": "h", "text": "Hoe een echte sessie eruitziet"}, {"t": "p", "text": "Niet één prompt en een afgeronde site. Een gesprek dat vernauwt."}, {"t": "demo", "kind": "session", "title": "Een echte sessie, opnieuw afgespeeld"}, {"t": "p", "text": "Let op wat daar gebeurt. De eerste uitwisseling levert geen enkele regel code op — ze levert overeenstemming op over wat er gebouwd wordt. De build komt daarna in stukken die klein genoeg zijn om te beoordelen. Als er iets mis is, is de melding specifiek, dus is de oplossing specifiek. Niets wordt vanaf nul herschreven, dus niets wat werkte stopt stilletjes met werken."}, {"t": "h", "text": "Waar het misgaat"}, {"t": "list", "items": ["**Alles in één keer vragen.** Je kunt een hele site niet in één keer nalezen, dus doe je het niet.", "**Vage probleemmeldingen.** ''Het is stuk'' levert een gok op. ''De nav overlapt de hero onder 480px'' levert een oplossing op.", "**Herschrijven in plaats van bijstellen.** Elke herschrijving brengt problemen terug die je al had opgelost.", "**Het geloven omdat het compileert.** Werkend en correct zijn verschillende woorden."]}, {"t": "prompt", "n": "06", "title": "Open een sessie zoals het hoort", "body": "We gaan {PROJECT} samen bouwen over meerdere berichten. Bevestig voordat er code komt dat je het volgende begrepen hebt, en vraag me naar alles wat onduidelijk is of ontbreekt.\n\nDoel: {ONE SENTENCE}\nDoelgroep: {WHO}\nEén actie die ze moeten ondernemen: {ACTION}\nHarde beperkingen: {LIST}\nVisuele richting: {LIST}\nTechnisch: gewone HTML, CSS en JavaScript in drie bestanden, geen libraries, moet werken vanaf 360px.\n\nStel daarna een bouwvolgorde voor — welk onderdeel we eerst maken, en waarom.", "why": {"context": "Alles wat het model nodig heeft, op één plek, aan het begin van de sessie.", "constraints": "Hier één keer genoemd in plaats van herhaald in elk volgend bericht.", "output": "Bevestiging, vragen en een bouwvolgorde — geen code tot het plan rond is.", "iteration": "Zijn vragen zijn de gaten in je eigen denken. Beantwoord ze goed; dat is de echte waarde van deze stap."}}, {"t": "task", "title": "Draai de workflow één keer, van begin tot eind", "steps": ["Kies iets echt kleins: één contactsectie.", "Schrijf stap 1 tot en met 5 uit in een tekstbestand voordat je Claude opent.", "Stuur de openingsprompt hierboven en beantwoord wat het vraagt.", "Vraag om de implementatie. Lees elke regel voordat je hem draait.", "Test op 360px en alleen met het toetsenbord. Meld één probleem precies.", "Itereer tot het klopt. Noteer hoeveel berichten het kostte."], "done": "Je hebt één volledige ronde afgerond. Elk project in deze cursus is deze ronde, herhaald op grotere schaal."}, {"t": "quiz", "q": "Waar gaan de meeste AI-ondersteunde builds echt mis?", "type": "single", "options": ["Het model produceert slechte code", "De developer begint bij stap 6 en slaat doel, context en beperkingen over", "De technologie is nog niet volwassen genoeg", "Er zijn niet genoeg goede prompttemplates beschikbaar"], "correct": [1], "why": "De code is meestal prima voor wat er gevraagd is. Wat ontbreekt, zijn de vijf stappen vóór het vragen — daarom levert hetzelfde model bij de een middelmatig werk en bij de ander uitstekend werk."}, {"t": "summary", "points": ["Een herhaalbare volgorde verslaat een slimme prompt.", "Stap 1 tot en met 5 gebeuren voordat er code bestaat, en bepalen de uitkomst.", "Bouw in stukken die klein genoeg zijn om echt na te lezen.", "Meld problemen precies; stel bij in plaats van te herschrijven."]}]'::jsonb, 6, true, 13, null, null),
  ('d9e8ff3b-1d9f-57f6-81e2-6533fe7e0eec', 'dc1a60ee-68f1-5dfe-908c-65b35b975f35', 'understanding-claude', 'Understanding Claude', 'What is actually happening when you send a message — and why that changes how you write one.', '[{"t": "h", "text": "It is completing your document."}, {"t": "p", "text": "Underneath the conversation, the model is doing one thing: reading everything in front of it and producing what most plausibly comes next. Not looking anything up. Not running your code. Reading the whole conversation as one document and continuing it."}, {"t": "p", "text": "That sounds reductive until you notice what follows from it. **Everything in the conversation shapes the answer** — your first message, its own earlier replies, the code you pasted, the tone you used. If you want a different answer, change the document."}, {"t": "figure", "kind": "context", "caption": "Everything visible to the model when it answers"}, {"t": "h", "text": "Three consequences you can act on"}, {"t": "p", "text": "**It has no memory between conversations.** Yesterday''s session is gone. Not hidden — gone. Re-establishing context at the start of a session is part of the job, not a workaround."}, {"t": "p", "text": "**Its own replies become part of the input.** If it makes a wrong assumption in message two and you do not correct it, that assumption is now context for messages three through twenty. Correct errors immediately, while they are cheap."}, {"t": "p", "text": "**Vagueness resolves to the average.** Ask for ''a modern website'' and you get the centre of everything that has ever been called modern. That is not the model failing; that is the only honest answer to an unspecific question."}, {"t": "callout", "kind": "note", "title": "Why generic output is your fault, in a useful way", "text": "This is good news. If the output is average because the input was unspecific, then specificity is a lever you control. Nothing needs to change about the tool for your results to get dramatically better."}, {"t": "h", "text": "Confidence is not a signal"}, {"t": "p", "text": "The model has no separate channel for uncertainty. A guess is written in the same voice as a fact. You cannot read confidence off the prose — which means checking is not paranoia, it is the only available method."}, {"t": "demo", "kind": "context-compare", "title": "Watch specificity change the answer"}, {"t": "prompt", "n": "01", "title": "Make it show its reasoning", "body": "Before you answer, tell me:\n1. What you understood my goal to be\n2. What you are assuming because I did not say\n3. What you would need to know to give a better answer\n\nThen answer.\n\nMy question: {QUESTION}", "why": {"context": "Forces the model''s interpretation into the open before it commits to an answer.", "constraints": "Three numbered items, in order, so it cannot skip the uncomfortable second one.", "output": "Its reading of you, its assumptions, its gaps — and only then the answer.", "iteration": "Item 2 is the gold. Every assumption listed is a decision you have not made yet."}}, {"t": "task", "title": "Find your own vagueness", "steps": ["Write a request for something you actually want to build.", "Run it through the prompt above rather than sending it directly.", "Read the assumptions it lists.", "Rewrite your original request so that at least three of those assumptions are no longer necessary."], "done": "You have watched a vague request become a specific one, and you can now feel the difference in the answers."}, {"t": "quiz", "q": "You start a new conversation and say ''continue where we left off yesterday''. What happens?", "type": "single", "options": ["It retrieves the previous conversation", "It has no access to it and will either say so or invent a plausible continuation", "It searches your project files", "It asks you to authenticate"], "correct": [1], "why": "A new conversation is empty. The second half of that answer is the dangerous part: asked to continue something it cannot see, a model may produce a fluent continuation of a conversation that never happened."}, {"t": "summary", "points": ["The model continues the document in front of it. That document is your whole conversation.", "No memory across sessions; its own replies become context within one.", "Vague input resolves to average output — which makes specificity your lever.", "Confidence carries no information about correctness."]}]'::jsonb, 'Claude begrijpen', 'Wat er werkelijk gebeurt als je een bericht verstuurt — en waarom dat verandert hoe je er een schrijft.', '[{"t": "h", "text": "Het vult je document aan."}, {"t": "p", "text": "Onder het gesprek doet het model één ding: alles lezen wat voor hem ligt en produceren wat daar het meest plausibel op volgt. Niets opzoeken. Je code niet uitvoeren. Het hele gesprek lezen als één document en het voortzetten."}, {"t": "p", "text": "Dat klinkt simplistisch tot je ziet wat eruit volgt. **Alles in het gesprek bepaalt het antwoord** — je eerste bericht, zijn eigen eerdere antwoorden, de code die je plakte, de toon die je aansloeg. Wil je een ander antwoord, verander dan het document."}, {"t": "figure", "kind": "context", "caption": "Alles wat het model ziet op het moment dat het antwoordt"}, {"t": "h", "text": "Drie gevolgen waar je iets mee kunt"}, {"t": "p", "text": "**Het heeft geen geheugen tussen gesprekken.** De sessie van gisteren is weg. Niet verborgen — weg. Aan het begin van een sessie opnieuw context opbouwen hoort bij het werk; het is geen omweg."}, {"t": "p", "text": "**Zijn eigen antwoorden worden onderdeel van de input.** Maakt het in bericht twee een verkeerde aanname en corrigeer je die niet, dan is die aanname context voor bericht drie tot en met twintig. Corrigeer fouten meteen, zolang ze goedkoop zijn."}, {"t": "p", "text": "**Vaagheid lost op in het gemiddelde.** Vraag om ‘een moderne website’ en je krijgt het midden van alles wat ooit modern is genoemd. Dat is geen falen van het model; dat is het enige eerlijke antwoord op een niet-specifieke vraag."}, {"t": "callout", "kind": "note", "title": "Waarom generieke output jouw schuld is, op een nuttige manier", "text": "Dat is goed nieuws. Als de output gemiddeld is omdat de input niet specifiek was, dan is specificiteit een knop die jij bedient. Er hoeft niets aan het gereedschap te veranderen om je resultaten drastisch beter te maken."}, {"t": "h", "text": "Stelligheid is geen signaal"}, {"t": "p", "text": "Het model heeft geen apart kanaal voor onzekerheid. Een gok wordt in dezelfde stem geschreven als een feit. Je kunt zekerheid niet aan het proza aflezen — controleren is dus geen paranoia, het is de enige methode die je hebt."}, {"t": "demo", "kind": "context-compare", "title": "Zie specificiteit het antwoord veranderen"}, {"t": "prompt", "n": "01", "title": "Laat het zijn redenering tonen", "body": "Voordat je antwoordt, vertel me:\n1. Wat je denkt dat mijn doel is\n2. Wat je aanneemt omdat ik het niet heb gezegd\n3. Wat je zou moeten weten om een beter antwoord te geven\n\nGeef daarna pas antwoord.\n\nMijn vraag: {QUESTION}", "why": {"context": "Dwingt de interpretatie van het model naar buiten voordat het zich aan een antwoord vastlegt.", "constraints": "Drie genummerde punten, op volgorde, zodat het het ongemakkelijke tweede punt niet kan overslaan.", "output": "Zijn lezing van jou, zijn aannames, zijn hiaten — en pas dan het antwoord.", "iteration": "Punt 2 is het goud. Elke aanname die er staat is een beslissing die jij nog niet hebt genomen."}}, {"t": "task", "title": "Vind je eigen vaagheid", "steps": ["Schrijf een verzoek voor iets dat je echt wilt bouwen.", "Haal het door de prompt hierboven in plaats van het direct te versturen.", "Lees de aannames die het opsomt.", "Herschrijf je oorspronkelijke verzoek zo dat minstens drie van die aannames niet langer nodig zijn."], "done": "Je hebt een vaag verzoek zien veranderen in een specifiek verzoek, en je voelt nu het verschil in de antwoorden."}, {"t": "quiz", "q": "Je begint een nieuw gesprek en zegt ‘ga verder waar we gisteren gebleven waren’. Wat gebeurt er?", "type": "single", "options": ["Het haalt het vorige gesprek op", "Het heeft er geen toegang toe en zal dat zeggen of een plausibele voortzetting verzinnen", "Het doorzoekt je projectbestanden", "Het vraagt je om in te loggen"], "correct": [1], "why": "Een nieuw gesprek is leeg. De tweede helft van dat antwoord is het gevaarlijke deel: gevraagd om iets voort te zetten wat het niet kan zien, produceert een model soms een vloeiende voortzetting van een gesprek dat nooit heeft plaatsgevonden."}, {"t": "summary", "points": ["Het model zet het document voort dat voor hem ligt. Dat document is je hele gesprek.", "Geen geheugen tussen sessies; binnen één sessie worden zijn eigen antwoorden context.", "Vage input lost op in gemiddelde output — en dat maakt specificiteit jouw knop.", "Stelligheid zegt niets over correctheid."]}]'::jsonb, 1, true, 10, null, null),
  ('c1b203c6-c249-5eed-9719-7b371f5764c5', 'dc1a60ee-68f1-5dfe-908c-65b35b975f35', 'how-claude-interprets-instructions', 'How Claude interprets instructions', 'The gap between what you said and what you meant, and how to close it.', '[{"t": "h", "text": "It does what you said."}, {"t": "p", "text": "Almost every ''the AI got it wrong'' moment is really a gap between the instruction and the intention. The model resolved an ambiguity you did not know you had left open. Learning to spot those ambiguities before you send is most of what prompting is."}, {"t": "h", "text": "Where the gaps hide"}, {"t": "p", "text": "**Words that sound like specifications but are not.** Modern, clean, professional, nice, sleek, minimal. Each one is a compliment about a result, not an instruction about how to get there. Two people using ''minimal'' can mean opposite layouts."}, {"t": "p", "text": "**Scope you assumed was obvious.** ''Fix the header'' — only the header, or also the navigation inside it? ''Make it responsive'' — down to what width? On what device?"}, {"t": "p", "text": "**Silence about what must not change.** You ask for a colour change. You get a colour change and a restructured layout, because nothing said the layout was settled."}, {"t": "figure", "kind": "anatomy", "caption": "The four parts of an instruction that lands"}, {"t": "h", "text": "The fix: say what you mean by the word"}, {"t": "p", "text": "Do not remove ''minimal'' from your vocabulary. Define it inline. ''Minimal — meaning one accent colour, no borders, no shadows, whitespace instead of dividers.'' Now it is checkable, and you have also just clarified it for yourself."}, {"t": "code", "lang": "js", "filename": "before-and-after.txt", "code": "// vague\n\"Make the card look better and more modern.\"\n\n// specific\n\"Increase the card''s internal padding to 32px, remove the drop\n shadow, replace the 1px border with a 1px hairline in --line,\n and set the title to the h3 size from the type scale.\n Do not change the layout or the copy.\""}, {"t": "callout", "kind": "tip", "title": "Add the fence", "text": "Almost every change instruction should end with a sentence saying what must stay the same. ''Do not change the layout, the copy, or the class names.'' One line, and you stop getting helpful surprises."}, {"t": "h", "text": "Literal by default"}, {"t": "p", "text": "Ask for ''a few examples'' and you might get three, or seven. Ask for three and you get three. Numbers, file names, element names and exact values all collapse ambiguity for free — use them wherever you actually have a preference."}, {"t": "demo", "kind": "instruction-gap", "title": "Spot the ambiguity"}, {"t": "prompt", "n": "02", "title": "Have it find your ambiguities first", "body": "Here is an instruction I am about to send you:\n\n\"{YOUR INSTRUCTION}\"\n\nDo not carry it out. Instead, list every way it could reasonably be interpreted differently from what I probably meant. For each, say what extra sentence would remove the ambiguity.", "why": {"context": "Your real instruction, examined before it costs you a wrong build.", "constraints": "''Do not carry it out'' is essential or you get the work instead of the review.", "output": "A list of ambiguities with the exact sentence that closes each one.", "iteration": "Paste the improved instruction back and compare the result with what you would have got."}}, {"t": "task", "title": "Rewrite three instructions", "steps": ["Take these: ''make it look professional'', ''fix the mobile version'', ''clean up this code''.", "Rewrite each one so that a stranger could tell whether it had been done correctly.", "Send both versions of one of them in separate conversations.", "Compare the two results side by side."], "done": "You have measured the cost of a vague instruction in output quality, on your own work."}, {"t": "quiz", "q": "You ask for a colour change and get a redesigned layout as well. What was missing?", "type": "single", "options": ["A more powerful model", "A sentence saying what must not change", "More detail about the colour", "A shorter prompt"], "correct": [1], "why": "Without a fence, an unmentioned area is fair game. Naming what is settled is as important as naming what should change — and it takes one sentence."}, {"t": "summary", "points": ["Wrong output is usually an ambiguity you left open.", "Adjectives like ''modern'' and ''clean'' specify nothing until you define them inline.", "State scope: what changes, and explicitly what does not.", "Exact numbers and names remove ambiguity at no cost."]}]'::jsonb, 'Hoe Claude instructies interpreteert', 'Het gat tussen wat je zei en wat je bedoelde, en hoe je het dicht.', '[{"t": "h", "text": "Het doet wat je zei."}, {"t": "p", "text": "Bijna elk ‘de AI deed het verkeerd’-moment is in werkelijkheid een gat tussen de instructie en de bedoeling. Het model loste een dubbelzinnigheid op waarvan je niet wist dat je die had opengelaten. Die dubbelzinnigheden leren zien vóór je verstuurt is het grootste deel van prompten."}, {"t": "h", "text": "Waar de gaten zich verstoppen"}, {"t": "p", "text": "**Woorden die als specificatie klinken maar het niet zijn.** Modern, clean, professioneel, mooi, strak, minimaal. Stuk voor stuk een compliment over een resultaat, geen instructie over hoe je daar komt. Twee mensen die ‘minimaal’ zeggen kunnen tegenovergestelde layouts bedoelen."}, {"t": "p", "text": "**Scope waarvan je aannam dat die duidelijk was.** ‘Fix de header’ — alleen de header, of ook de navigatie erin? ‘Maak het responsive’ — tot welke breedte? Op welk apparaat?"}, {"t": "p", "text": "**Stilte over wat niet mag veranderen.** Je vraagt om een kleurwijziging. Je krijgt een kleurwijziging en een herbouwde layout, omdat nergens stond dat de layout vaststond."}, {"t": "figure", "kind": "anatomy", "caption": "De vier onderdelen van een instructie die aankomt"}, {"t": "h", "text": "De oplossing: zeg wat je met het woord bedoelt"}, {"t": "p", "text": "Schrap ‘minimaal’ niet uit je vocabulaire. Definieer het ter plekke. ‘Minimaal — dus één accentkleur, geen randen, geen schaduwen, whitespace in plaats van scheidingslijnen.’ Nu is het controleerbaar, en je hebt het meteen ook voor jezelf helder gemaakt."}, {"t": "code", "lang": "js", "filename": "before-and-after.txt", "code": "// vague\n\"Make the card look better and more modern.\"\n\n// specific\n\"Increase the card''s internal padding to 32px, remove the drop\n shadow, replace the 1px border with a 1px hairline in --line,\n and set the title to the h3 size from the type scale.\n Do not change the layout or the copy.\""}, {"t": "callout", "kind": "tip", "title": "Zet er een hek omheen", "text": "Bijna elke wijzigingsinstructie hoort te eindigen met een zin die zegt wat hetzelfde moet blijven. ‘Verander de layout, de teksten en de class-namen niet.’ Eén regel, en je krijgt geen behulpzame verrassingen meer."}, {"t": "h", "text": "Standaard letterlijk"}, {"t": "p", "text": "Vraag om ‘een paar voorbeelden’ en je krijgt er drie, of zeven. Vraag om drie en je krijgt er drie. Getallen, bestandsnamen, elementnamen en exacte waarden ruimen dubbelzinnigheid gratis op — gebruik ze overal waar je echt een voorkeur hebt."}, {"t": "demo", "kind": "instruction-gap", "title": "Zie de dubbelzinnigheid"}, {"t": "prompt", "n": "02", "title": "Laat het eerst je dubbelzinnigheden vinden", "body": "Hier is een instructie die ik je zo wil sturen:\n\n\"{YOUR INSTRUCTION}\"\n\nVoer hem niet uit. Som in plaats daarvan elke manier op waarop hij redelijkerwijs anders geïnterpreteerd kan worden dan ik waarschijnlijk bedoelde. Zeg bij elk geval welke extra zin de dubbelzinnigheid zou wegnemen.", "why": {"context": "Je echte instructie, onderzocht voordat hij je een verkeerde build kost.", "constraints": "‘Voer hem niet uit’ is essentieel, anders krijg je het werk in plaats van de review.", "output": "Een lijst met dubbelzinnigheden, en bij elke de exacte zin die haar sluit.", "iteration": "Plak de verbeterde instructie terug en vergelijk het resultaat met wat je anders had gekregen."}}, {"t": "task", "title": "Herschrijf drie instructies", "steps": ["Neem deze: ‘maak het professioneel’, ‘fix de mobiele versie’, ‘ruim deze code op’.", "Herschrijf ze allemaal zo dat een vreemde kan vaststellen of het correct is uitgevoerd.", "Stuur van één ervan beide versies in aparte gesprekken.", "Vergelijk de twee resultaten naast elkaar."], "done": "Je hebt de prijs van een vage instructie gemeten in outputkwaliteit, op je eigen werk."}, {"t": "quiz", "q": "Je vraagt om een kleurwijziging en krijgt er een herontworpen layout bij. Wat ontbrak er?", "type": "single", "options": ["Een krachtiger model", "Een zin die zegt wat niet mag veranderen", "Meer detail over de kleur", "Een kortere prompt"], "correct": [1], "why": "Zonder hek is alles wat je niet noemt vrij spel. Benoemen wat vaststaat is net zo belangrijk als benoemen wat moet veranderen — en het kost één zin."}, {"t": "summary", "points": ["Verkeerde output is meestal een dubbelzinnigheid die jij hebt opengelaten.", "Woorden als ‘modern’ en ‘clean’ specificeren niets tot je ze ter plekke definieert.", "Benoem de scope: wat verandert, en expliciet wat niet.", "Exacte getallen en namen halen dubbelzinnigheid weg zonder dat het iets kost."]}]'::jsonb, 2, true, 11, null, null),
  ('de3d626d-cf1f-53db-89b2-409d0c4eebee', 'dc1a60ee-68f1-5dfe-908c-65b35b975f35', 'context', 'Context', 'The single highest-leverage thing you control.', '[{"t": "h", "text": "Context is everything."}, {"t": "p", "text": "Claude can only work with the information you give it. Not your repository, not your client meeting, not the thing you decided in the shower. If it is not in the conversation, it does not exist — and the model will fill the gap with the most average plausible thing."}, {"t": "figure", "kind": "context", "caption": "The four kinds of context, and what each one buys you"}, {"t": "h", "text": "The four kinds worth giving"}, {"t": "p", "text": "**Project context** — what you are building and who for. Changes structure and tone.\n**Technical context** — stack, files, versions, conventions. Changes the code shape.\n**Design context** — tokens, references, rules. Changes how it looks.\n**Conversational context** — what you already agreed. Changes how much you have to repeat."}, {"t": "h", "text": "More is not automatically better"}, {"t": "p", "text": "Pasting your entire codebase is not context, it is noise. The useful test for any piece of information: **would the answer be different without it?** If not, leave it out. A focused 200 words beats an unfocused 2,000."}, {"t": "demo", "kind": "context-compare", "title": "The same request at three levels of context"}, {"t": "callout", "kind": "tip", "title": "Keep a project brief", "text": "Write your goal, audience, stack, conventions and design tokens once, in a text file. Paste it at the top of any new session. Ten seconds of copying replaces ten minutes of re-explaining, and the model stops rediscovering your project every day."}, {"t": "h", "text": "Context decays as a session grows"}, {"t": "p", "text": "In a long conversation, something said early can lose against forty messages of more recent material. When a rule you set at the start starts slipping, restate it. Not as a complaint — as a line: ''Reminder: three files, no libraries, tokens only.'' It works, and it costs nothing."}, {"t": "code", "lang": "js", "filename": "project-brief.txt", "code": "PROJECT — Vlaam Bakery, one page\nAUDIENCE — locals, mostly on phones, mostly before 9am\nONE ACTION — see today''s bread and the opening hours\nSTACK — plain HTML/CSS/JS, three files, no libraries\nCONVENTIONS — BEM class names, tokens on :root, no inline styles\nTOKENS — --ink #0d0d0d  --paper #fff  --accent #c6ff4a\n          --space 8px  --radius 24px\nCONSTRAINTS — works from 360px, no stock photography,\n              readable in bright daylight on a phone"}, {"t": "prompt", "n": "03", "title": "Open with a brief", "body": "{PASTE YOUR PROJECT BRIEF}\n\nThat is the whole project. Read it back to me in three sentences so I can check you have understood it, and tell me the single most important decision that the brief does not yet answer.\n\nDo not write code yet.", "why": {"context": "The entire brief in one message, so nothing has to be inferred.", "constraints": "A read-back in three sentences forces compression, which exposes misunderstanding.", "output": "Confirmation plus the most important missing decision.", "iteration": "Answer that question, add it to the brief file, and reuse the improved brief next session."}}, {"t": "task", "title": "Write your brief", "steps": ["Create `brief.txt` and fill in the six lines from the example for a project you want to build.", "Open a session with the prompt above.", "Answer the missing decision it identifies and add the answer to the file.", "Keep the file. You will paste it at the start of every session from here on."], "done": "You have a reusable context block. This one file will save you more time than any prompt template."}, {"t": "quiz", "q": "Which piece of context would most change the answer to ''build me a hero section''?", "type": "single", "options": ["That you prefer tabs to spaces", "That the visitors are nervous first-time patients and the one action is booking", "That you are using VS Code", "That you would like it to look nice"], "correct": [1], "why": "Audience and the single action change the message, the hierarchy, the tone and the layout. Editor and indentation change nothing about the design, and ''look nice'' specifies nothing at all."}, {"t": "summary", "points": ["If it is not in the conversation, it does not exist.", "Four kinds: project, technical, design, conversational.", "Judge each addition by whether it would change the answer.", "Keep a brief file and reuse it; restate key rules in long sessions."]}]'::jsonb, 'Context', 'Het krachtigste dat je zelf in handen hebt.', '[{"t": "h", "text": "Context is alles."}, {"t": "p", "text": "Claude kan alleen werken met de informatie die je geeft. Niet met je repository, niet met je klantgesprek, niet met wat je onder de douche bedacht. Wat niet in het gesprek staat, bestaat niet — en het model vult het gat met het meest gemiddelde plausibele antwoord."}, {"t": "figure", "kind": "context", "caption": "De vier soorten context, en wat elke soort je oplevert"}, {"t": "h", "text": "De vier soorten die het waard zijn"}, {"t": "p", "text": "**Projectcontext** — wat je bouwt en voor wie. Verandert structuur en toon.\n**Technische context** — stack, bestanden, versies, conventies. Verandert de vorm van de code.\n**Designcontext** — tokens, referenties, regels. Verandert hoe het eruitziet.\n**Gesprekscontext** — wat je al hebt afgesproken. Verandert hoeveel je moet herhalen."}, {"t": "h", "text": "Meer is niet vanzelf beter"}, {"t": "p", "text": "Je hele codebase plakken is geen context, dat is ruis. De bruikbare test voor elk stuk informatie: **zou het antwoord anders zijn zonder dit?** Zo nee, laat het weg. Tweehonderd gerichte woorden verslaan tweeduizend ongerichte."}, {"t": "demo", "kind": "context-compare", "title": "Hetzelfde verzoek op drie niveaus van context"}, {"t": "callout", "kind": "tip", "title": "Houd een projectbrief bij", "text": "Schrijf je doel, doelgroep, stack, conventies en design tokens één keer op, in een tekstbestand. Plak het bovenaan elke nieuwe sessie. Tien seconden kopiëren vervangt tien minuten opnieuw uitleggen, en het model hoeft je project niet elke dag opnieuw te ontdekken."}, {"t": "h", "text": "Context slijt naarmate een sessie groeit"}, {"t": "p", "text": "In een lang gesprek kan iets dat vroeg is gezegd het verliezen van veertig berichten recenter materiaal. Als een regel die je aan het begin stelde begint weg te glijden, herhaal hem. Niet als klacht — als regel: ‘Ter herinnering: drie bestanden, geen libraries, alleen tokens.’ Het werkt, en het kost niets."}, {"t": "code", "lang": "js", "filename": "project-brief.txt", "code": "PROJECT — Vlaam Bakery, one page\nAUDIENCE — locals, mostly on phones, mostly before 9am\nONE ACTION — see today''s bread and the opening hours\nSTACK — plain HTML/CSS/JS, three files, no libraries\nCONVENTIONS — BEM class names, tokens on :root, no inline styles\nTOKENS — --ink #0d0d0d  --paper #fff  --accent #c6ff4a\n          --space 8px  --radius 24px\nCONSTRAINTS — works from 360px, no stock photography,\n              readable in bright daylight on a phone"}, {"t": "prompt", "n": "03", "title": "Open met een brief", "body": "{PASTE YOUR PROJECT BRIEF}\n\nDat is het hele project. Lees het in drie zinnen aan me terug zodat ik kan controleren of je het begrepen hebt, en noem me de belangrijkste beslissing die de brief nog niet beantwoordt.\n\nSchrijf nog geen code.", "why": {"context": "De hele brief in één bericht, zodat er niets afgeleid hoeft te worden.", "constraints": "Terugkoppelen in drie zinnen dwingt tot compressie, en compressie legt misverstanden bloot.", "output": "Bevestiging plus de belangrijkste ontbrekende beslissing.", "iteration": "Beantwoord die vraag, zet het antwoord in het briefbestand en hergebruik de verbeterde brief volgende sessie."}}, {"t": "task", "title": "Schrijf je brief", "steps": ["Maak `brief.txt` en vul de zes regels uit het voorbeeld in voor een project dat je wilt bouwen.", "Open een sessie met de prompt hierboven.", "Beantwoord de ontbrekende beslissing die het aanwijst en zet het antwoord in het bestand.", "Bewaar het bestand. Vanaf nu plak je het aan het begin van elke sessie."], "done": "Je hebt een herbruikbaar contextblok. Dit ene bestand bespaart je meer tijd dan welke prompttemplate ook."}, {"t": "quiz", "q": "Welk stuk context verandert het antwoord op ‘bouw een hero section voor me’ het meest?", "type": "single", "options": ["Dat je tabs boven spaties verkiest", "Dat de bezoekers zenuwachtige nieuwe patiënten zijn en de ene actie het maken van een afspraak is", "Dat je VS Code gebruikt", "Dat je het er graag mooi uit wilt laten zien"], "correct": [1], "why": "Doelgroep en de ene actie veranderen de boodschap, de hiërarchie, de toon en de layout. Editor en inspringing veranderen niets aan het ontwerp, en ‘mooi’ specificeert helemaal niets."}, {"t": "summary", "points": ["Wat niet in het gesprek staat, bestaat niet.", "Vier soorten: project, technisch, design, gesprek.", "Beoordeel elke toevoeging op de vraag of ze het antwoord zou veranderen.", "Houd een briefbestand bij en hergebruik het; herhaal kernregels in lange sessies."]}]'::jsonb, 3, true, 12, null, null),
  ('540607d6-2024-5e62-a5c1-dfac3e17edee', 'dc1a60ee-68f1-5dfe-908c-65b35b975f35', 'writing-your-first-development-prompt', 'Writing your first development prompt', 'The six-part structure, used on something real.', '[{"t": "h", "text": "Six parts, in this order."}, {"t": "p", "text": "A development prompt that works has the same shape every time. Not a template to paste — a checklist to run through, so nothing important is left to inference."}, {"t": "figure", "kind": "anatomy", "caption": "The six parts of a development prompt"}, {"t": "list", "ordered": true, "items": ["**Goal** — what this thing must do, in one sentence.", "**Context** — who it is for, what it is part of, what already exists.", "**Constraints** — what is ruled out. Technical and creative.", "**Direction** — the specific visual or structural decisions you have already made.", "**Scope** — exactly what you want back, and what you do not.", "**Output format** — files, language, whether you want explanation with it."]}, {"t": "h", "text": "Watch it assemble"}, {"t": "p", "text": "Start with the request everyone writes, then add one part at a time and notice what each addition removes from the space of possible answers."}, {"t": "code", "lang": "js", "filename": "assembling.txt", "code": "1  Build a hero section.\n\n2  + goal\n   Build a hero section whose job is to get a visitor to book a table.\n\n3  + context\n   ...for a twelve-seat restaurant. Visitors are mostly on phones,\n   deciding between three places, in a hurry.\n\n4  + constraints\n   ...Plain HTML and CSS, no libraries, no stock photography,\n   readable at 360px, supporting line under 20 words.\n\n5  + direction\n   ...Oversized headline set tight, one accent colour, generous\n   whitespace, asymmetric, no card, no gradient.\n\n6  + scope and output\n   Return only the HTML and CSS for this section, using the tokens\n   below. Then list three decisions I might disagree with."}, {"t": "p", "text": "Line 1 could be answered ten thousand ways. Line 6 could be answered perhaps a dozen — and all dozen are things you would consider shipping. That narrowing is the entire skill."}, {"t": "demo", "kind": "prompt-builder", "title": "Build one, part by part"}, {"t": "callout", "kind": "note", "title": "You are also writing this for yourself", "text": "Half the value arrives before you press send. You cannot state the goal, the audience and the one action without deciding them — and most weak websites are weak because nobody ever did."}, {"t": "prompt", "n": "04", "title": "Your first real development prompt", "body": "GOAL — Build a hero section that gets a visitor to {ACTION}.\n\nCONTEXT — This is the first screen of a one-page site for {WHO}. Visitors are {AUDIENCE}, usually on a phone, usually deciding between options.\n\nCONSTRAINTS — Plain HTML and CSS. No libraries. No stock photography. Must be readable at 360px. Supporting line under 20 words.\n\nDIRECTION — Oversized headline set tight. One accent colour. Generous whitespace. Asymmetric composition. No card, no gradient, no shadow.\n\nTOKENS —\n{PASTE TOKENS}\n\nSCOPE — This section only. Do not build the rest of the page.\n\nOUTPUT — The HTML and the CSS, in two blocks. Then list three decisions I might reasonably disagree with.", "why": {"context": "Audience and situation are stated, so hierarchy and tone follow from something real.", "constraints": "Six exclusions, each removing a default the model would otherwise reach for.", "output": "One section, two blocks, plus a list of debatable calls — reviewable in one sitting.", "iteration": "Argue with one of the three decisions. That exchange teaches you more than the code did."}}, {"t": "task", "title": "Send it for real", "steps": ["Fill in every placeholder for a project of your own.", "Send it. Save the result as `index.html` and `styles.css`.", "Open it at 360px wide and read it as if you were the visitor.", "Pick one of the three decisions it listed and push back on it.", "Keep the improved version."], "done": "You have written a complete development prompt and had a real exchange about the result. Every build from here is this, at a larger scale."}, {"t": "quiz", "q": "Which part of the six is most often missing, and most expensive when it is?", "type": "single", "options": ["Output format", "Constraints", "Goal", "Scope"], "correct": [1], "why": "Constraints are what remove wrong answers. Without them the output is defensible but generic, and you spend the next hour discovering one by one what you did not want."}, {"t": "summary", "points": ["Goal, context, constraints, direction, scope, output — in that order.", "Each part narrows the space of possible answers.", "Scope to one piece so you can genuinely review it.", "Ask for debatable decisions and argue with one."]}]'::jsonb, 'Je eerste ontwikkelprompt schrijven', 'De structuur van zes onderdelen, toegepast op iets echts.', '[{"t": "h", "text": "Zes onderdelen, in deze volgorde."}, {"t": "p", "text": "Een ontwikkelprompt die werkt heeft elke keer dezelfde vorm. Geen template om te plakken — een checklist om langs te lopen, zodat niets belangrijks aan gissen wordt overgelaten."}, {"t": "figure", "kind": "anatomy", "caption": "De zes onderdelen van een ontwikkelprompt"}, {"t": "list", "ordered": true, "items": ["**Doel** — wat dit ding moet doen, in één zin.", "**Context** — voor wie het is, waar het deel van uitmaakt, wat er al bestaat.", "**Beperkingen** — wat is uitgesloten. Technisch en creatief.", "**Richting** — de concrete visuele of structurele beslissingen die je al hebt genomen.", "**Scope** — precies wat je terug wilt, en wat niet.", "**Outputformaat** — bestanden, taal, en of je er uitleg bij wilt."]}, {"t": "h", "text": "Zie hem opgebouwd worden"}, {"t": "p", "text": "Begin met het verzoek dat iedereen schrijft, voeg dan één onderdeel per keer toe en let op wat elke toevoeging weghaalt uit de ruimte van mogelijke antwoorden."}, {"t": "code", "lang": "js", "filename": "assembling.txt", "code": "1  Build a hero section.\n\n2  + goal\n   Build a hero section whose job is to get a visitor to book a table.\n\n3  + context\n   ...for a twelve-seat restaurant. Visitors are mostly on phones,\n   deciding between three places, in a hurry.\n\n4  + constraints\n   ...Plain HTML and CSS, no libraries, no stock photography,\n   readable at 360px, supporting line under 20 words.\n\n5  + direction\n   ...Oversized headline set tight, one accent colour, generous\n   whitespace, asymmetric, no card, no gradient.\n\n6  + scope and output\n   Return only the HTML and CSS for this section, using the tokens\n   below. Then list three decisions I might disagree with."}, {"t": "p", "text": "Regel 1 kun je op tienduizend manieren beantwoorden. Regel 6 op misschien een stuk of twaalf — en alle twaalf zijn dingen die je zou overwegen te publiceren. Die vernauwing is de hele vaardigheid."}, {"t": "demo", "kind": "prompt-builder", "title": "Bouw er een, onderdeel voor onderdeel"}, {"t": "callout", "kind": "note", "title": "Je schrijft dit ook voor jezelf", "text": "De helft van de waarde komt binnen voordat je op versturen drukt. Je kunt het doel, de doelgroep en de ene actie niet benoemen zonder ze te beslissen — en de meeste zwakke websites zijn zwak omdat niemand dat ooit deed."}, {"t": "prompt", "n": "04", "title": "Je eerste echte ontwikkelprompt", "body": "DOEL — Bouw een hero section die een bezoeker aanzet tot {ACTION}.\n\nCONTEXT — Dit is het eerste scherm van een one-page site voor {WHO}. Bezoekers zijn {AUDIENCE}, meestal op een telefoon, meestal kiezend tussen opties.\n\nBEPERKINGEN — Alleen HTML en CSS. Geen libraries. Geen stockfotografie. Moet leesbaar zijn op 360px. Ondersteunende regel onder de 20 woorden.\n\nRICHTING — Overmaatse kop, strak gezet. Eén accentkleur. Royale whitespace. Asymmetrische compositie. Geen card, geen gradient, geen schaduw.\n\nTOKENS —\n{PASTE TOKENS}\n\nSCOPE — Alleen deze sectie. Bouw de rest van de pagina niet.\n\nOUTPUT — De HTML en de CSS, in twee blokken. Noem daarna drie beslissingen waar ik het redelijkerwijs niet mee eens zou kunnen zijn.", "why": {"context": "Doelgroep en situatie staan er, dus hiërarchie en toon volgen uit iets echts.", "constraints": "Zes uitsluitingen, elk goed voor één standaardkeuze die het model anders zou pakken.", "output": "Eén sectie, twee blokken, plus een lijst met discutabele keuzes — in één keer te beoordelen.", "iteration": "Ga in tegen een van de drie beslissingen. Dat gesprek leert je meer dan de code deed."}}, {"t": "task", "title": "Verstuur hem echt", "steps": ["Vul elke placeholder in voor een eigen project.", "Verstuur hem. Sla het resultaat op als `index.html` en `styles.css`.", "Open het op 360px breed en lees het alsof je de bezoeker bent.", "Kies een van de drie genoemde beslissingen en ga ertegenin.", "Bewaar de verbeterde versie."], "done": "Je hebt een volledige ontwikkelprompt geschreven en een echt gesprek gevoerd over het resultaat. Elke build hierna is dit, op grotere schaal."}, {"t": "quiz", "q": "Welk van de zes onderdelen ontbreekt het vaakst, en kost dan het meest?", "type": "single", "options": ["Outputformaat", "Beperkingen", "Doel", "Scope"], "correct": [1], "why": "Beperkingen zijn wat de verkeerde antwoorden weghaalt. Zonder beperkingen is de output verdedigbaar maar generiek, en besteed je het volgende uur aan één voor één ontdekken wat je niet wilde."}, {"t": "summary", "points": ["Doel, context, beperkingen, richting, scope, output — in die volgorde.", "Elk onderdeel vernauwt de ruimte van mogelijke antwoorden.", "Beperk de scope tot één stuk, zodat je het echt kunt beoordelen.", "Vraag om discutabele beslissingen en ga tegen één ervan in."]}]'::jsonb, 4, true, 13, null, null),
  ('439befb3-f1f5-5767-84c1-0a0a410e7c97', 'dc1a60ee-68f1-5dfe-908c-65b35b975f35', 'good-prompts-vs-bad-prompts', 'Good prompts vs bad prompts', 'Six real pairs, and what separates them.', '[{"t": "h", "text": "The difference is never length."}, {"t": "p", "text": "It is whether a stranger could tell if the result was correct. That is the test. Run any prompt through it and you will know immediately whether it is doing any work."}, {"t": "demo", "kind": "versus", "title": "Six pairs, side by side"}, {"t": "h", "text": "Pair one — the layout"}, {"t": "p", "text": "**Weak:** Make the page layout better.\n**Strong:** The three sections currently stack in one column at every width. Above 900px, put the image and the text side by side at 5:7, with 48px between them. Keep the stacked order on mobile."}, {"t": "p", "text": "''Better'' cannot be checked. Widths, ratios and gaps can be measured with a ruler."}, {"t": "h", "text": "Pair two — the bug"}, {"t": "p", "text": "**Weak:** The menu is broken.\n**Strong:** Tapping the menu button below 768px opens the panel, but tapping it again does not close it. Console shows no errors. It worked before I added the scroll listener in script.js line 40."}, {"t": "p", "text": "The second gives expected, actual, boundary and timing — four facts, and the cause is usually obvious from them alone."}, {"t": "h", "text": "Pair three — the style"}, {"t": "p", "text": "**Weak:** Make it feel premium.\n**Strong:** Premium here means: one accent colour used no more than twice per screen, headline tracking at -0.03em, no shadows, hairline borders in --line, and at least 96px of vertical space between sections."}, {"t": "p", "text": "Same word, defined inline. Now it is five checkable rules instead of a hope."}, {"t": "h", "text": "Pair four — the refactor"}, {"t": "p", "text": "**Weak:** Clean up this code.\n**Strong:** This file repeats the same card markup four times with different text. Extract it into one function that takes title, body and href. Do not change the rendered HTML or the class names."}, {"t": "h", "text": "Pair five — the exploration"}, {"t": "p", "text": "**Weak:** Give me some options for the hero.\n**Strong:** Give me three hero variations that differ only in composition: one centred, one left-aligned with the image right, one full-bleed with the headline overlaid. Same copy and tokens in all three."}, {"t": "h", "text": "Pair six — the review"}, {"t": "p", "text": "**Weak:** Is this good?\n**Strong:** Review this section for spacing consistency against the 8px scale, type scale adherence, contrast ratios, and keyboard operability. List findings worst-first with the reason. Do not fix anything yet."}, {"t": "callout", "kind": "tip", "title": "The stranger test", "text": "Could someone who has never met you tell whether the result satisfies the prompt? If not, the prompt is a wish. Rewrite it until the answer is yes."}, {"t": "prompt", "n": "05", "title": "Grade your own prompt", "body": "Grade this prompt out of 10 on: clarity of goal, sufficiency of context, quality of constraints, checkability of the result.\n\n\"{YOUR PROMPT}\"\n\nFor each category, say what is missing and give the exact sentence that would fix it. Then show me the rewritten prompt.", "why": {"context": "Four named categories rather than a general opinion.", "constraints": "Asking for the exact fixing sentence prevents ''be more specific'' as feedback.", "output": "Scores, gaps, fixes and a rewrite you can use immediately.", "iteration": "Run both versions and compare. You only need to do this a few times before you internalise it."}}, {"t": "task", "title": "Grade three of your own", "steps": ["Find three prompts you have actually sent this week.", "Run each through the grading prompt.", "Note which category scores lowest across all three — that is your personal weak spot.", "Write one sentence you will add to every prompt from now on to cover it."], "done": "You know your own failure pattern, which is more useful than any template."}, {"t": "quiz", "q": "Which prompt gives Claude the most useful context?", "type": "prompt", "options": ["Make a website.", "Make a modern website for my business.", "Build a responsive landing page for a premium architecture studio: 12-column grid, oversized headlines, three project rows, one call to action, no stock imagery.", "Build a website with a hero, about, services and contact section."], "correct": [2], "why": "Only the third names the subject, the structure, the visual direction and an exclusion. The fourth names sections but leaves every judgement open — organised, and still says nothing."}, {"t": "summary", "points": ["The test is checkability, not length.", "Define your adjectives inline or they specify nothing.", "For bugs: expected, actual, boundary, timing.", "For options: name the axis they should differ on."]}]'::jsonb, 'Goede prompts versus slechte prompts', 'Zes echte paren, en wat ze van elkaar onderscheidt.', '[{"t": "h", "text": "Het verschil is nooit de lengte."}, {"t": "p", "text": "Het gaat erom of een vreemde kan vaststellen of het resultaat klopt. Dat is de test. Haal er elke prompt doorheen en je weet meteen of hij iets doet."}, {"t": "demo", "kind": "versus", "title": "Zes paren, naast elkaar"}, {"t": "h", "text": "Paar één — de layout"}, {"t": "p", "text": "**Zwak:** Maak de layout van de pagina beter.\n**Sterk:** De drie secties stapelen nu op elke breedte in één kolom. Zet boven 900px de afbeelding en de tekst naast elkaar in verhouding 5:7, met 48px ertussen. Houd op mobiel de gestapelde volgorde aan."}, {"t": "p", "text": "‘Beter’ valt niet te controleren. Breedtes, verhoudingen en tussenruimtes kun je met een liniaal nameten."}, {"t": "h", "text": "Paar twee — de bug"}, {"t": "p", "text": "**Zwak:** Het menu is kapot.\n**Sterk:** Onder 768px opent het paneel als je op de menuknop tikt, maar een tweede tik sluit hem niet. De console toont geen fouten. Het werkte nog voordat ik de scroll listener toevoegde op regel 40 van script.js."}, {"t": "p", "text": "De tweede geeft verwacht, werkelijk, grens en moment — vier feiten, en daaruit alleen al is de oorzaak meestal duidelijk."}, {"t": "h", "text": "Paar drie — de stijl"}, {"t": "p", "text": "**Zwak:** Laat het premium aanvoelen.\n**Sterk:** Premium betekent hier: één accentkleur die niet vaker dan twee keer per scherm voorkomt, koppen met -0.03em tracking, geen schaduwen, haarlijnranden in --line, en minstens 96px verticale ruimte tussen secties."}, {"t": "p", "text": "Hetzelfde woord, ter plekke gedefinieerd. Nu zijn het vijf controleerbare regels in plaats van een hoop."}, {"t": "h", "text": "Paar vier — de refactor"}, {"t": "p", "text": "**Zwak:** Ruim deze code op.\n**Sterk:** Dit bestand herhaalt dezelfde card-markup vier keer met andere tekst. Haal die naar één functie die title, body en href aanneemt. Verander de gerenderde HTML en de class-namen niet."}, {"t": "h", "text": "Paar vijf — de verkenning"}, {"t": "p", "text": "**Zwak:** Geef me wat opties voor de hero.\n**Sterk:** Geef me drie hero-varianten die alleen in compositie verschillen: één gecentreerd, één links uitgelijnd met de afbeelding rechts, één full-bleed met de kop eroverheen. Dezelfde tekst en tokens in alle drie."}, {"t": "h", "text": "Paar zes — de review"}, {"t": "p", "text": "**Zwak:** Is dit goed?\n**Sterk:** Beoordeel deze sectie op consistente spacing tegen de 8px-schaal, naleving van de typeschaal, contrastverhoudingen en bedienbaarheid met het toetsenbord. Som de bevindingen op, de ergste eerst, met de reden erbij. Repareer nog niets."}, {"t": "callout", "kind": "tip", "title": "De vreemdentest", "text": "Zou iemand die je nooit heeft ontmoet kunnen vaststellen of het resultaat aan de prompt voldoet? Zo niet, dan is de prompt een wens. Herschrijf hem tot het antwoord ja is."}, {"t": "prompt", "n": "05", "title": "Beoordeel je eigen prompt", "body": "Geef deze prompt een cijfer van 1 tot 10 op: helderheid van het doel, toereikendheid van de context, kwaliteit van de beperkingen, controleerbaarheid van het resultaat.\n\n\"{YOUR PROMPT}\"\n\nZeg per categorie wat er ontbreekt en geef de exacte zin die het zou oplossen. Laat me daarna de herschreven prompt zien.", "why": {"context": "Vier benoemde categorieën in plaats van een algemene mening.", "constraints": "Om de exacte herstelzin vragen voorkomt ‘wees specifieker’ als feedback.", "output": "Cijfers, hiaten, oplossingen en een herschrijving die je meteen kunt gebruiken.", "iteration": "Stuur beide versies en vergelijk. Een paar keer doen is genoeg voordat het erin zit."}}, {"t": "task", "title": "Beoordeel drie van je eigen prompts", "steps": ["Zoek drie prompts die je deze week echt hebt verstuurd.", "Haal ze allemaal door de beoordelingsprompt.", "Kijk welke categorie over alle drie het laagst scoort — dat is jouw persoonlijke zwakke plek.", "Schrijf één zin die je vanaf nu aan elke prompt toevoegt om dat af te dekken."], "done": "Je kent je eigen faalpatroon, en dat is bruikbaarder dan welke template ook."}, {"t": "quiz", "q": "Welke prompt geeft Claude de nuttigste context?", "type": "prompt", "options": ["Maak een website.", "Maak een moderne website voor mijn bedrijf.", "Bouw een responsive landingspagina voor een premium architectenbureau: 12-koloms grid, overmaatse koppen, drie projectrijen, één call to action, geen stockbeeld.", "Bouw een website met een hero, een over-ons-sectie, een dienstensectie en een contactsectie."], "correct": [2], "why": "Alleen de derde benoemt het onderwerp, de structuur, de visuele richting en een uitsluiting. De vierde benoemt secties maar laat elk oordeel open — netjes geordend, en zegt nog steeds niets."}, {"t": "summary", "points": ["De test is controleerbaarheid, niet lengte.", "Definieer je bijvoeglijke naamwoorden ter plekke, anders specificeren ze niets.", "Bij bugs: verwacht, werkelijk, grens, moment.", "Bij varianten: benoem de as waarop ze moeten verschillen."]}]'::jsonb, 5, true, 12, null, null),
  ('80efd315-a318-54be-b303-beb9dac3d7d1', 'dc1a60ee-68f1-5dfe-908c-65b35b975f35', 'giving-claude-constraints', 'Giving Claude constraints', 'Every constraint removes a wrong answer. That is the whole mechanism.', '[{"t": "h", "text": "Constraints are not restrictions. They are direction."}, {"t": "p", "text": "Without them, the model chooses from everything it has ever seen and lands on the middle. Each constraint you add deletes a region of that space. Enough of them and what remains is your work rather than the average of everyone''s."}, {"t": "figure", "kind": "narrowing", "caption": "What each constraint removes"}, {"t": "h", "text": "Five kinds"}, {"t": "p", "text": "**Technical** — plain HTML/CSS/JS, three files, no libraries, must work in Safari 16.\n**Structural** — one h1, semantic landmarks, no nested grids deeper than two.\n**Visual** — one accent colour, no shadows, no gradients, hairline borders only.\n**Behavioural** — works without JavaScript, keyboard operable, respects reduced motion.\n**Negative** — no cards, no carousels, no stock photography, no emoji."}, {"t": "callout", "kind": "note", "title": "Negative constraints are underrated", "text": "Saying what you do not want is often faster and more precise than describing what you do. ''No cards'' rules out a whole family of layouts in two words, and forces something more considered in their place."}, {"t": "h", "text": "Make them checkable"}, {"t": "p", "text": "A constraint you cannot verify is a preference. ''Fast'' is a preference. ''No single asset over 200KB, no layout shift on load'' is a constraint — you can open the Network panel and settle it."}, {"t": "code", "lang": "js", "filename": "constraints.txt", "code": "preference          →  constraint\n\nfast                →  no asset over 200KB, no layout shift\naccessible          →  keyboard operable, contrast 4.5:1, visible focus\nresponsive          →  no horizontal scroll from 360px to 1920px\nclean code          →  no repeated values, tokens only, no file over 300 lines\nsubtle animation    →  transform and opacity only, nothing over 600ms"}, {"t": "demo", "kind": "constraint-lab", "title": "Add constraints, watch the space shrink"}, {"t": "h", "text": "How many is too many"}, {"t": "p", "text": "Constraints that conflict produce confused output. If you ask for maximum whitespace and maximum information density, something has to give and the model will pick for you. When results start feeling compromised, look for two rules pulling in opposite directions and decide which one you actually care about."}, {"t": "prompt", "n": "06", "title": "A constraint block you can reuse", "body": "For everything in this session, these constraints apply. Confirm them once, then hold them without me repeating myself.\n\nTECHNICAL — plain HTML, CSS and JavaScript in three files. No libraries, no build step, no external requests except Google Fonts.\n\nSTRUCTURAL — semantic HTML, one h1 per page, no heading levels skipped, all interactive elements are real buttons or links.\n\nVISUAL — only the tokens I have given you. No shadows, no gradients, no rounded corners beyond --radius. One accent colour, used sparingly.\n\nBEHAVIOURAL — keyboard operable with visible focus. Contrast at least 4.5:1. Full prefers-reduced-motion path. Page is meaningful with JavaScript disabled.\n\nNEGATIVE — no card layouts, no carousels, no stock photography, no emoji, no lorem ipsum.\n\nIf a request of mine would break one of these, say so instead of quietly ignoring it.", "why": {"context": "Session-wide, so later prompts can be short.", "constraints": "All five kinds, each item checkable.", "output": "A confirmation now; compliance for the rest of the session.", "iteration": "The last line is the one that matters most — it turns silent compromises into a conversation."}}, {"t": "task", "title": "Write your own block", "steps": ["Copy the constraint block and adapt every line to how you actually want to work.", "Save it as `constraints.txt` next to your project brief.", "Use it to open your next session.", "Each time you find yourself correcting the same thing twice, add a line."], "done": "You have a reusable standard. Your prompts get shorter and your output gets better at the same time."}, {"t": "quiz", "q": "Which of these are constraints in the useful sense?", "type": "multi", "options": ["No external libraries", "Make it look premium", "No horizontal scroll from 360px upward", "Animate transform and opacity only"], "correct": [0, 2, 3], "why": "Three of them can be verified by someone who has never met you. ''Premium'' cannot be checked until you define what you mean by it — at which point it becomes several real constraints."}, {"t": "summary", "points": ["Each constraint deletes a region of possible answers.", "Five kinds: technical, structural, visual, behavioural, negative.", "If you cannot verify it, it is a preference — rewrite it.", "Keep a reusable constraint block and ask to be told when a request conflicts with it."]}]'::jsonb, 'Claude beperkingen geven', 'Elke beperking haalt een verkeerd antwoord weg. Dat is het hele mechanisme.', '[{"t": "h", "text": "Beperkingen zijn geen belemmering. Ze zijn richting."}, {"t": "p", "text": "Zonder beperkingen kiest het model uit alles wat het ooit heeft gezien en landt het in het midden. Elke beperking die je toevoegt wist een deel van die ruimte. Genoeg beperkingen en wat overblijft is jouw werk in plaats van het gemiddelde van iedereen."}, {"t": "figure", "kind": "narrowing", "caption": "Wat elke beperking weghaalt"}, {"t": "h", "text": "Vijf soorten"}, {"t": "p", "text": "**Technisch** — alleen HTML/CSS/JS, drie bestanden, geen libraries, moet werken in Safari 16.\n**Structureel** — één h1, semantische landmarks, geen geneste grids dieper dan twee.\n**Visueel** — één accentkleur, geen schaduwen, geen gradients, alleen haarlijnranden.\n**Gedrag** — werkt zonder JavaScript, bedienbaar met het toetsenbord, respecteert reduced motion.\n**Negatief** — geen cards, geen carousels, geen stockfotografie, geen emoji."}, {"t": "callout", "kind": "note", "title": "Negatieve beperkingen worden onderschat", "text": "Zeggen wat je niet wilt is vaak sneller en preciezer dan beschrijven wat je wel wilt. ‘Geen cards’ sluit in twee woorden een hele familie layouts uit, en dwingt tot iets doordachters op die plek."}, {"t": "h", "text": "Maak ze controleerbaar"}, {"t": "p", "text": "Een beperking die je niet kunt verifiëren is een voorkeur. ‘Snel’ is een voorkeur. ‘Geen enkele asset groter dan 200KB, geen layout shift bij het laden’ is een beperking — je opent het Network-paneel en de kwestie is beslecht."}, {"t": "code", "lang": "js", "filename": "constraints.txt", "code": "preference          →  constraint\n\nfast                →  no asset over 200KB, no layout shift\naccessible          →  keyboard operable, contrast 4.5:1, visible focus\nresponsive          →  no horizontal scroll from 360px to 1920px\nclean code          →  no repeated values, tokens only, no file over 300 lines\nsubtle animation    →  transform and opacity only, nothing over 600ms"}, {"t": "demo", "kind": "constraint-lab", "title": "Voeg beperkingen toe en zie de ruimte krimpen"}, {"t": "h", "text": "Hoeveel is te veel"}, {"t": "p", "text": "Beperkingen die botsen leveren verwarde output op. Vraag je om maximale whitespace en maximale informatiedichtheid, dan moet er iets wijken en kiest het model voor jou. Als resultaten gecompromitteerd beginnen te voelen, zoek dan de twee regels die tegengesteld trekken en beslis welke je echt belangrijk vindt."}, {"t": "prompt", "n": "06", "title": "Een beperkingenblok dat je kunt hergebruiken", "body": "Voor alles in deze sessie gelden deze beperkingen. Bevestig ze één keer en houd je er daarna aan zonder dat ik het herhaal.\n\nTECHNISCH — alleen HTML, CSS en JavaScript in drie bestanden. Geen libraries, geen build step, geen externe requests behalve Google Fonts.\n\nSTRUCTUREEL — semantische HTML, één h1 per pagina, geen overgeslagen kopniveaus, alle interactieve elementen zijn echte buttons of links.\n\nVISUEEL — alleen de tokens die ik je heb gegeven. Geen schaduwen, geen gradients, geen afgeronde hoeken buiten --radius. Eén accentkleur, spaarzaam gebruikt.\n\nGEDRAG — bedienbaar met het toetsenbord, met zichtbare focus. Contrast minstens 4.5:1. Volledig pad voor prefers-reduced-motion. De pagina is betekenisvol met JavaScript uitgeschakeld.\n\nNEGATIEF — geen card-layouts, geen carousels, geen stockfotografie, geen emoji, geen lorem ipsum.\n\nAls een verzoek van mij een van deze regels zou breken, zeg dat dan in plaats van het stilzwijgend te negeren.", "why": {"context": "Geldt voor de hele sessie, zodat latere prompts kort kunnen zijn.", "constraints": "Alle vijf soorten, elk punt controleerbaar.", "output": "Nu een bevestiging; naleving voor de rest van de sessie.", "iteration": "De laatste regel is de belangrijkste — die maakt van stilzwijgende compromissen een gesprek."}}, {"t": "task", "title": "Schrijf je eigen blok", "steps": ["Kopieer het beperkingenblok en pas elke regel aan op hoe jij echt wilt werken.", "Sla het op als `constraints.txt` naast je projectbrief.", "Open je volgende sessie ermee.", "Elke keer dat je hetzelfde voor de tweede keer corrigeert, voeg je een regel toe."], "done": "Je hebt een herbruikbare standaard. Je prompts worden korter en je output wordt tegelijk beter."}, {"t": "quiz", "q": "Welke hiervan zijn beperkingen in de bruikbare zin?", "type": "multi", "options": ["Geen externe libraries", "Laat het er premium uitzien", "Geen horizontale scroll vanaf 360px", "Animeer alleen transform en opacity"], "correct": [0, 2, 3], "why": "Drie ervan kan iemand die je nooit heeft ontmoet verifiëren. ‘Premium’ valt niet te controleren tot je definieert wat je ermee bedoelt — en op dat moment worden het meerdere echte beperkingen."}, {"t": "summary", "points": ["Elke beperking wist een deel van de mogelijke antwoorden.", "Vijf soorten: technisch, structureel, visueel, gedrag, negatief.", "Kun je het niet verifiëren, dan is het een voorkeur — herschrijf het.", "Houd een herbruikbaar beperkingenblok bij en vraag om een melding zodra een verzoek ermee botst."]}]'::jsonb, 6, true, 11, null, null),
  ('72346335-c0c7-5609-a8ab-a7dbd69ea32e', 'dc1a60ee-68f1-5dfe-908c-65b35b975f35', 'giving-claude-design-direction', 'Giving Claude design direction', 'How to describe a look precisely enough that it can be built.', '[{"t": "h", "text": "Describe decisions, not impressions."}, {"t": "p", "text": "''Modern'', ''clean'', ''premium'', ''bold'' are reactions to a finished thing. They cannot be executed. Design direction that works names the decisions that produce the reaction — and those you can state, check and argue about."}, {"t": "h", "text": "The five axes"}, {"t": "p", "text": "**Typography** — families, scale, weights, tracking, line height, how large the largest thing is.\n**Space** — the base unit, the section rhythm, how much air around the type.\n**Colour** — how many, in what roles, how often the accent appears.\n**Composition** — grid, symmetry, alignment, where the eye lands first.\n**Motion** — what moves, how far, how fast, and what stays still."}, {"t": "figure", "kind": "axes", "caption": "Five axes — a look is a position on each"}, {"t": "p", "text": "Any style you admire can be described as a position on those five. Do that and you have a brief. Say ''modern'' and you have a mood."}, {"t": "h", "text": "Translating a reference honestly"}, {"t": "p", "text": "Naming a site you like is a shortcut that mostly fails — the model has an average impression of it at best, and you may not agree on what makes it good. Instead, look at the thing you like and write down what it is doing."}, {"t": "code", "lang": "js", "filename": "translating.txt", "code": "\"like a Swiss design annual\"\n\n→ TYPE   one grotesque, three sizes only, headline at 8vw,\n         tracking -0.04em, body at 17px / 1.6\n→ SPACE  8px base, 128px between sections, 64px gutters\n→ COLOUR paper, ink, one accent used twice per page\n→ COMP   12-column grid, hard left alignment, asymmetric,\n         generous margins, no centred text\n→ MOTION reveals under 600ms, transform and opacity only,\n         nothing loops, nothing bounces"}, {"t": "demo", "kind": "direction-lab", "title": "Move one axis at a time"}, {"t": "callout", "kind": "tip", "title": "Change one axis per iteration", "text": "If a result is not right, resist rewriting the whole direction. Move one axis — make the headline larger, or double the section spacing — and look again. You learn what each axis is worth, and you stop losing the parts that were already good."}, {"t": "h", "text": "Give tokens, not adjectives"}, {"t": "p", "text": "The strongest version of design direction is not prose at all. It is a block of custom properties plus three sentences of composition rules. The model then has your system rather than an interpretation of your mood."}, {"t": "prompt", "n": "07", "title": "Design direction that can be executed", "body": "Here is the design direction. Use it exactly; do not introduce values outside it.\n\nTYPOGRAPHY — Display: {FAMILY}, weight 500, tracking -0.03em, line-height 0.98. Body: {FAMILY}, 17px, line-height 1.6. Labels: monospace, 11px, uppercase, tracking 0.16em. Five sizes total, no others.\n\nSPACE — 8px base unit. Section padding 120px top and bottom. Container 1280px with 24px gutters.\n\nCOLOUR — {TOKENS}. The accent appears at most twice per screen. No shadows. Borders are 1px in --line only.\n\nCOMPOSITION — 12-column grid, left-aligned, asymmetric. Nothing centred except a deliberate full-screen statement. Whitespace instead of dividers.\n\nMOTION — reveals 560ms, UI transitions 280ms, one easing curve. Transform and opacity only.\n\nBuild {SECTION} to this direction. Then tell me which of these rules you found hardest to satisfy and why.", "why": {"context": "A complete system rather than a mood, so nothing has to be guessed.", "constraints": "''No values outside this'' is what stops a fourteenth grey appearing in section three.", "output": "The section, plus the friction points — which are where your system is weak.", "iteration": "Fix the system, not the section. Then rebuild and everything downstream improves."}}, {"t": "task", "title": "Translate something you like", "steps": ["Find a site whose design you admire.", "Write down its position on all five axes. Measure where you can — use the inspector.", "Turn that into a direction block like the one above.", "Build one section to it, and compare against the original."], "done": "You have converted taste into instructions. This is the skill that separates directing a model from hoping."}, {"t": "quiz", "q": "Which of these gives real design direction?", "type": "single", "options": ["Make it modern and clean", "Use a nice font and good spacing", "One grotesque, three sizes, headline at 8vw with -0.04em tracking, 128px between sections, one accent used twice per page", "Make it look like a high-end agency site"], "correct": [2], "why": "Only the third names decisions that can be executed and checked. The others describe a feeling and leave every actual choice to the model — which will resolve them into the most average version of that feeling."}, {"t": "summary", "points": ["Name decisions, not impressions.", "Five axes: typography, space, colour, composition, motion.", "Translate references by measuring them, not by naming them.", "Tokens plus three composition rules beat any amount of adjective."]}]'::jsonb, 'Claude designrichting geven', 'Hoe je een look precies genoeg beschrijft om hem te kunnen bouwen.', '[{"t": "h", "text": "Beschrijf beslissingen, geen indrukken."}, {"t": "p", "text": "‘Modern’, ‘clean’, ‘premium’ en ‘bold’ zijn reacties op iets dat af is. Ze zijn niet uit te voeren. Designrichting die werkt benoemt de beslissingen die de reactie veroorzaken — en die kun je uitspreken, controleren en bediscussiëren."}, {"t": "h", "text": "De vijf assen"}, {"t": "p", "text": "**Typografie** — families, schaal, gewichten, tracking, regelhoogte, hoe groot het grootste ding is.\n**Ruimte** — de basiseenheid, het ritme van de secties, hoeveel lucht er om de tekst staat.\n**Kleur** — hoeveel, in welke rollen, hoe vaak het accent verschijnt.\n**Compositie** — grid, symmetrie, uitlijning, waar het oog het eerst landt.\n**Beweging** — wat beweegt, hoe ver, hoe snel, en wat stil blijft staan."}, {"t": "figure", "kind": "axes", "caption": "Vijf assen — een look is een positie op elk daarvan"}, {"t": "p", "text": "Elke stijl die je bewondert laat zich beschrijven als een positie op die vijf. Doe dat en je hebt een brief. Zeg ‘modern’ en je hebt een stemming."}, {"t": "h", "text": "Een referentie eerlijk vertalen"}, {"t": "p", "text": "Een site noemen die je mooi vindt is een sluiproute die meestal mislukt — het model heeft er hooguit een gemiddelde indruk van, en jullie zijn het misschien niet eens over wat hem goed maakt. Kijk in plaats daarvan naar wat je mooi vindt en schrijf op wat het doet."}, {"t": "code", "lang": "js", "filename": "translating.txt", "code": "\"like a Swiss design annual\"\n\n→ TYPE   one grotesque, three sizes only, headline at 8vw,\n         tracking -0.04em, body at 17px / 1.6\n→ SPACE  8px base, 128px between sections, 64px gutters\n→ COLOUR paper, ink, one accent used twice per page\n→ COMP   12-column grid, hard left alignment, asymmetric,\n         generous margins, no centred text\n→ MOTION reveals under 600ms, transform and opacity only,\n         nothing loops, nothing bounces"}, {"t": "demo", "kind": "direction-lab", "title": "Verschuif één as per keer"}, {"t": "callout", "kind": "tip", "title": "Verander één as per iteratie", "text": "Als een resultaat niet klopt, herschrijf dan niet de hele richting. Verschuif één as — maak de kop groter, of verdubbel de ruimte tussen de secties — en kijk opnieuw. Je leert wat elke as waard is, en je raakt de delen die al goed waren niet meer kwijt."}, {"t": "h", "text": "Geef tokens, geen bijvoeglijke naamwoorden"}, {"t": "p", "text": "De sterkste vorm van designrichting is helemaal geen proza. Het is een blok custom properties plus drie zinnen compositieregels. Het model heeft dan jouw systeem in plaats van een interpretatie van je stemming."}, {"t": "prompt", "n": "07", "title": "Designrichting die uitvoerbaar is", "body": "Dit is de designrichting. Gebruik hem exact; introduceer geen waarden die er niet in staan.\n\nTYPOGRAFIE — Display: {FAMILY}, gewicht 500, tracking -0.03em, line-height 0.98. Body: {FAMILY}, 17px, line-height 1.6. Labels: monospace, 11px, hoofdletters, tracking 0.16em. Vijf groottes in totaal, geen andere.\n\nRUIMTE — basiseenheid 8px. Sectiepadding 120px boven en onder. Container 1280px met 24px gutters.\n\nKLEUR — {TOKENS}. Het accent verschijnt hoogstens twee keer per scherm. Geen schaduwen. Randen zijn 1px en uitsluitend in --line.\n\nCOMPOSITIE — 12-koloms grid, links uitgelijnd, asymmetrisch. Niets gecentreerd, behalve een bewust statement over het volle scherm. Whitespace in plaats van scheidingslijnen.\n\nBEWEGING — reveals 560ms, UI-transities 280ms, één easing-curve. Alleen transform en opacity.\n\nBouw {SECTION} volgens deze richting. Vertel me daarna welke van deze regels je het lastigst vond om te volgen, en waarom.", "why": {"context": "Een compleet systeem in plaats van een stemming, zodat er niets te raden valt.", "constraints": "‘Geen waarden hierbuiten’ is wat voorkomt dat er in sectie drie een veertiende grijs opduikt.", "output": "De sectie, plus de wrijvingspunten — en dat is precies waar je systeem zwak is.", "iteration": "Repareer het systeem, niet de sectie. Bouw daarna opnieuw en alles stroomafwaarts wordt beter."}}, {"t": "task", "title": "Vertaal iets dat je mooi vindt", "steps": ["Zoek een site waarvan je het ontwerp bewondert.", "Schrijf zijn positie op alle vijf assen op. Meet waar je kunt — gebruik de inspector.", "Maak daar een richtingsblok van zoals hierboven.", "Bouw er één sectie mee en vergelijk die met het origineel."], "done": "Je hebt smaak omgezet in instructies. Dit is de vaardigheid die een model aansturen onderscheidt van hopen."}, {"t": "quiz", "q": "Welke hiervan geeft echte designrichting?", "type": "single", "options": ["Maak het modern en clean", "Gebruik een mooi font en goede spacing", "Eén grotesque, drie groottes, kop op 8vw met -0.04em tracking, 128px tussen secties, één accent dat twee keer per pagina terugkomt", "Laat het lijken op de site van een high-end bureau"], "correct": [2], "why": "Alleen de derde benoemt beslissingen die uitgevoerd en gecontroleerd kunnen worden. De andere beschrijven een gevoel en laten elke echte keuze aan het model — dat ze oplost in de meest gemiddelde versie van dat gevoel."}, {"t": "summary", "points": ["Benoem beslissingen, geen indrukken.", "Vijf assen: typografie, ruimte, kleur, compositie, beweging.", "Vertaal referenties door ze te meten, niet door ze te noemen.", "Tokens plus drie compositieregels verslaan elke hoeveelheid bijvoeglijke naamwoorden."]}]'::jsonb, 7, true, 13, null, null),
  ('b85386df-0da0-5ee1-8c8d-e690fa32a252', 'dc1a60ee-68f1-5dfe-908c-65b35b975f35', 'working-with-existing-code', 'Working with existing code', 'The skill that matters once your project is bigger than one file.', '[{"t": "h", "text": "Fencing the change."}, {"t": "p", "text": "Building from nothing is the easy case. The real work is changing something that already exists without breaking the parts that were fine. Do that badly and every fix costs you two regressions."}, {"t": "h", "text": "Give the minimum that makes the answer correct"}, {"t": "p", "text": "Not the whole repository. Not one isolated line either. The relevant piece, plus whatever it depends on — the tokens it uses, the markup it styles, the function it calls. If you cannot decide, ask what else it needs to see before it answers."}, {"t": "code", "lang": "js", "filename": "how-to-ask.txt", "code": "Here is the component I want to change:\n{THE COMPONENT}\n\nHere are the tokens it uses:\n{TOKENS}\n\nHere is the markup it styles:\n{MARKUP}\n\nCHANGE — the card padding from 24px to 32px and the title\n         from the h4 size to the h3 size.\n\nDO NOT CHANGE — the layout, the class names, the markup\n         structure, or anything outside this component.\n\nReturn only the lines that changed, with two lines of\ncontext either side."}, {"t": "callout", "kind": "tip", "title": "Ask for a diff, not a file", "text": "''Return only the lines that changed'' is the single most useful habit in this lesson. You can review six lines properly. You cannot review a regenerated 400-line file, so you will skim it, and something will slip through."}, {"t": "h", "text": "State your conventions once"}, {"t": "p", "text": "Naming, file structure, whether you use classes or utilities, how you handle state. Say it once at the start of a session and it applies to everything after. Say it never and you will spend the session renaming things by hand."}, {"t": "demo", "kind": "diff-review", "title": "Review a change properly"}, {"t": "h", "text": "When it rewrites more than you asked"}, {"t": "p", "text": "This will happen. The response is not to accept it and tidy up afterwards — it is to say so plainly: ''That changed the layout as well. Give me only the padding and font-size change, with the layout untouched.'' Being specific about the overreach gets you a corrected diff rather than another full rewrite."}, {"t": "h", "text": "Understand before you change"}, {"t": "p", "text": "If you are about to modify code you do not understand — generated or inherited — spend one message on comprehension first. It is faster than the debugging session you are otherwise scheduling for yourself."}, {"t": "prompt", "n": "08", "title": "Understand first, then change", "body": "Here is a file I did not write:\n\n{PASTE}\n\nBefore any changes, explain it to me:\n1. What it does, in two sentences\n2. What each function is responsible for\n3. What it assumes about the rest of the project\n4. Anything here that would surprise me later\n\nDo not suggest improvements and do not change anything yet.", "why": {"context": "The actual file, so the explanation is about your code and not a generic pattern.", "constraints": "Numbered, and explicitly no changes — comprehension is the whole deliverable.", "output": "Understanding, plus the assumptions and traps you would otherwise find at the worst moment.", "iteration": "Now make your change, and you will be able to tell whether the answer is right."}}, {"t": "task", "title": "Change one thing, safely", "steps": ["Take a file from an earlier lesson that you no longer remember in detail.", "Run the comprehension prompt above and read the answer.", "Ask for one small change, with an explicit do-not-change list, and request only the changed lines.", "Apply the diff by hand. Reload and confirm nothing else moved."], "done": "You have made a surgical change to code you did not write. That is the daily reality of working on anything real."}, {"t": "quiz", "q": "What is the most reliable way to stop a small change turning into a rewrite?", "type": "single", "options": ["Paste less code", "Name what must not change, and ask for only the changed lines", "Ask for a shorter answer", "Use a more capable model"], "correct": [1], "why": "The fence plus the diff request is what does it. Pasting less removes context the model needs; asking for brevity does not stop it touching the layout."}, {"t": "summary", "points": ["Give the relevant code plus what it depends on — not everything, not one line.", "Always name what must not change.", "Ask for changed lines only, so you can actually review them.", "Understand unfamiliar code before you modify it."]}]'::jsonb, 'Werken met bestaande code', 'De vaardigheid die telt zodra je project groter is dan één bestand.', '[{"t": "h", "text": "Een hek om de wijziging."}, {"t": "p", "text": "Vanaf nul bouwen is het makkelijke geval. Het echte werk is iets veranderen dat al bestaat zonder de delen te breken die in orde waren. Doe je dat slecht, dan kost elke fix je twee regressies."}, {"t": "h", "text": "Geef het minimum dat het antwoord juist maakt"}, {"t": "p", "text": "Niet de hele repository. Ook niet één losse regel. Het relevante stuk, plus waar het van afhangt — de tokens die het gebruikt, de markup die het opmaakt, de functie die het aanroept. Kun je niet kiezen, vraag dan wat het nog meer moet zien voordat het antwoordt."}, {"t": "code", "lang": "js", "filename": "how-to-ask.txt", "code": "Here is the component I want to change:\n{THE COMPONENT}\n\nHere are the tokens it uses:\n{TOKENS}\n\nHere is the markup it styles:\n{MARKUP}\n\nCHANGE — the card padding from 24px to 32px and the title\n         from the h4 size to the h3 size.\n\nDO NOT CHANGE — the layout, the class names, the markup\n         structure, or anything outside this component.\n\nReturn only the lines that changed, with two lines of\ncontext either side."}, {"t": "callout", "kind": "tip", "title": "Vraag om een diff, niet om een bestand", "text": "‘Geef alleen de regels die veranderd zijn’ is de nuttigste gewoonte uit deze les. Zes regels kun je fatsoenlijk beoordelen. Een opnieuw gegenereerd bestand van 400 regels niet, dus scan je het, en glipt er iets doorheen."}, {"t": "h", "text": "Benoem je conventies één keer"}, {"t": "p", "text": "Naamgeving, bestandsstructuur, of je classes of utilities gebruikt, hoe je state afhandelt. Zeg het één keer aan het begin van een sessie en het geldt voor alles daarna. Zeg het nooit en je besteedt de sessie aan het met de hand hernoemen van dingen."}, {"t": "demo", "kind": "diff-review", "title": "Beoordeel een wijziging fatsoenlijk"}, {"t": "h", "text": "Als het meer herschrijft dan je vroeg"}, {"t": "p", "text": "Dit gaat gebeuren. Het antwoord is niet om het te accepteren en achteraf op te ruimen — het is om het gewoon te zeggen: ‘Dat veranderde ook de layout. Geef me alleen de wijziging in padding en font-size, met de layout onaangetast.’ Specifiek zijn over wat er te veel is gedaan levert je een gecorrigeerde diff op in plaats van weer een volledige herschrijving."}, {"t": "h", "text": "Begrijp het voordat je het verandert"}, {"t": "p", "text": "Sta je op het punt code aan te passen die je niet begrijpt — gegenereerd of geërfd — besteed dan eerst één bericht aan begrip. Dat gaat sneller dan de debugsessie die je anders voor jezelf inplant."}, {"t": "prompt", "n": "08", "title": "Eerst begrijpen, dan veranderen", "body": "Hier is een bestand dat ik niet zelf heb geschreven:\n\n{PASTE}\n\nLeg het me uit voordat je iets verandert:\n1. Wat het doet, in twee zinnen\n2. Waar elke functie verantwoordelijk voor is\n3. Wat het aanneemt over de rest van het project\n4. Alles hierin dat me later zou kunnen verrassen\n\nStel geen verbeteringen voor en verander nog niets.", "why": {"context": "Het echte bestand, zodat de uitleg over jouw code gaat en niet over een algemeen patroon.", "constraints": "Genummerd, en expliciet geen wijzigingen — begrip is het hele resultaat.", "output": "Begrip, plus de aannames en valkuilen die je anders op het slechtst denkbare moment vindt.", "iteration": "Maak nu je wijziging, en je kunt zelf beoordelen of het antwoord klopt."}}, {"t": "task", "title": "Verander één ding, veilig", "steps": ["Pak een bestand uit een eerdere les dat je je niet meer in detail herinnert.", "Haal het door de begripsprompt hierboven en lees het antwoord.", "Vraag om één kleine wijziging, met een expliciete lijst van wat niet mag veranderen, en vraag alleen om de gewijzigde regels.", "Pas de diff met de hand toe. Herlaad en controleer dat er verder niets is verschoven."], "done": "Je hebt een chirurgische wijziging gemaakt in code die je niet zelf hebt geschreven. Dat is de dagelijkse werkelijkheid van werken aan iets echts."}, {"t": "quiz", "q": "Wat is de betrouwbaarste manier om te voorkomen dat een kleine wijziging een herschrijving wordt?", "type": "single", "options": ["Minder code plakken", "Benoem wat niet mag veranderen, en vraag alleen om de gewijzigde regels", "Om een korter antwoord vragen", "Een capabeler model gebruiken"], "correct": [1], "why": "Het hek plus het verzoek om een diff doet het werk. Minder plakken haalt context weg die het model nodig heeft; om beknoptheid vragen weerhoudt het er niet van de layout aan te raken."}, {"t": "summary", "points": ["Geef de relevante code plus waar die van afhangt — niet alles, niet één regel.", "Benoem altijd wat niet mag veranderen.", "Vraag alleen om de gewijzigde regels, zodat je ze echt kunt beoordelen.", "Begrijp onbekende code voordat je hem aanpast."]}]'::jsonb, 8, true, 14, null, null),
