insert into public.projects (id, level_id, slug, title, description, brief, title_nl, description_nl, brief_nl, is_final, position, published) values
  ('18d68115-d812-561b-a54e-2b81b97a20f0', '4b9dbcc2-d326-51f9-913a-3d45622166bd', 'first-landing-page', 'Build your first landing page', 'One page, one message, one call to action — built from a brief you write yourself.', '{"client": "A two-person photography studio moving from Instagram to a site of their own.", "goal": "A single page that makes someone email them.", "requirements": ["A hero with one clear message and one call to action", "A short about section written in the studio''s voice", "A grid of six work slots, drawn in CSS — no stock photography", "Working navigation, including on a phone", "Readable at 360px wide and at 1920px"], "prompts": ["project-scaffold", "hero-section", "responsive-pass"], "checklist": ["Project folder created with index.html, styles.css, script.js", "Hero written and built", "Navigation works on desktop and mobile", "Six work slots laid out on a grid", "Contact call to action reaches a real mailto or form", "Checked at 360px, 768px and 1440px", "No console errors"]}'::jsonb, 'Bouw je eerste landingspagina', 'Eén pagina, één boodschap, één call to action — gebouwd vanuit een briefing die je zelf schrijft.', '{"client": "Een fotostudio van twee personen die van Instagram naar een eigen site verhuist.", "goal": "Eén pagina die iemand aanzet om ze te mailen.", "requirements": ["Een hero met één duidelijke boodschap en één call to action", "Een korte over-ons-sectie, geschreven in de stem van de studio", "Een grid met zes werkvlakken, getekend in CSS — geen stockfotografie", "Werkende navigatie, ook op een telefoon", "Leesbaar op 360px breed en op 1920px"], "prompts": ["project-scaffold", "hero-section", "responsive-pass"], "checklist": ["Projectmap aangemaakt met index.html, styles.css, script.js", "Hero geschreven en gebouwd", "Navigatie werkt op desktop en op mobiel", "Zes werkvlakken in een grid geplaatst", "Contact-call-to-action komt uit bij een echte mailto of een formulier", "Gecontroleerd op 360px, 768px en 1440px", "Geen fouten in de console"]}'::jsonb, false, 1, true),
  ('03d78f90-6666-5f2e-96dd-e0150d78266e', '0a9dece4-ba97-5f92-8552-476a68ade471', 'premium-brand-website', 'Build a premium brand website', 'Take the same content and raise it to studio standard: a real type scale, a real spacing system, motion that means something.', '{"client": "A small furniture maker who sells through galleries and wants to be taken seriously online.", "goal": "A site that looks like it cost money, without a photo budget.", "requirements": ["A documented design system: colour tokens, type scale, spacing scale", "At least four reusable components built from those tokens", "One considered motion system with consistent easings and durations", "Keyboard operable end to end, with visible focus states", "No layout shift on load"], "prompts": ["design-system", "component-spec", "motion-system"], "checklist": ["Tokens defined in one place and used everywhere", "Type scale applied consistently", "Four or more components reused across sections", "Motion tiers defined and applied", "Focus states visible on every interactive element", "prefers-reduced-motion path implemented", "Lighthouse accessibility pass reviewed"]}'::jsonb, 'Bouw een premium merkwebsite', 'Neem dezelfde content en til hem naar studioniveau: een echte typeschaal, een echt spacingsysteem, beweging die iets betekent.', '{"client": "Een kleine meubelmaker die via galeries verkoopt en online serieus genomen wil worden.", "goal": "Een site die eruitziet alsof hij geld heeft gekost, zonder fotobudget.", "requirements": ["Een gedocumenteerd designsysteem: kleurtokens, typeschaal, spacingschaal", "Minstens vier herbruikbare componenten, gebouwd uit die tokens", "Eén doordacht bewegingssysteem met consistente easings en tijdsduren", "Van begin tot eind bedienbaar met het toetsenbord, met zichtbare focus-states", "Geen layout shift bij het laden"], "prompts": ["design-system", "component-spec", "motion-system"], "checklist": ["Tokens op één plek gedefinieerd en overal gebruikt", "Typeschaal consistent toegepast", "Vier of meer componenten hergebruikt in verschillende secties", "Bewegingsniveaus gedefinieerd en toegepast", "Focus-states zichtbaar op elk interactief element", "Variant voor prefers-reduced-motion geïmplementeerd", "Toegankelijkheidsrapport van Lighthouse doorgenomen"]}'::jsonb, false, 2, true),
  ('6bc22f1b-0081-5f30-8197-19c90f86223a', '6eb9b656-1b10-570e-9111-dd18aab1a90d', 'interactive-web-application', 'Build an interactive web application', 'Move past pages: state, data, forms and components that hold up when someone actually uses them.', '{"client": "A running club that wants members to log routes and see them on a shared board.", "goal": "An application, not a page — state that survives a refresh.", "requirements": ["A data model written down before any code", "Create, read, update and delete for one entity", "Form validation with useful error messages", "Loading, empty and error states for every view", "State that survives a page refresh"], "prompts": ["data-model", "state-management", "empty-states"], "checklist": ["Data model documented", "All four operations work", "Validation messages explain how to fix the problem", "Loading, empty and error states designed", "State restored after refresh", "No unhandled promise rejections in the console"]}'::jsonb, 'Bouw een interactieve webapplicatie', 'Voorbij de pagina: state, data, formulieren en componenten die standhouden als iemand ze echt gebruikt.', '{"client": "Een hardloopclub die wil dat leden routes bijhouden en ze op een gedeeld bord terugzien.", "goal": "Een applicatie, geen pagina — state die een refresh overleeft.", "requirements": ["Een datamodel dat is uitgeschreven voordat er code is", "Aanmaken, lezen, bijwerken en verwijderen voor één entiteit", "Formuliervalidatie met bruikbare foutmeldingen", "Loading-, lege en foutstates voor elke view", "State die een refresh van de pagina overleeft"], "prompts": ["data-model", "state-management", "empty-states"], "checklist": ["Datamodel gedocumenteerd", "Alle vier de operaties werken", "Validatiemeldingen leggen uit hoe je het probleem oplost", "Loading-, lege en foutstates ontworpen", "State hersteld na een refresh", "Geen onafgehandelde promise rejections in de console"]}'::jsonb, false, 3, true),
  ('25d69058-672b-5cb5-b60d-80a3983ab69b', '0e3df840-08ac-5805-9967-87d6016c8ea8', 'final-project', 'Final project — build your own complete website', 'A real client brief. Everything from the course, in one build, put online under your own name.', '{"client": "A fictional creative company of your choosing. Name it, give it a point of view, and write its copy yourself.", "goal": "A complete website that you would put in front of a paying client.", "requirements": ["Responsive from 360px to 1920px", "A deliberate type system, not defaults", "Working mobile navigation", "Motion that serves the content and respects reduced motion", "Interactions that actually work — no decoration pretending to be a control", "Keyboard accessible with visible focus", "Fast: no oversized assets, no layout shift", "Deployed to a live URL"], "prompts": ["project-scaffold", "design-system", "responsive-pass", "final-qa"], "checklist": ["Brief written: client, audience, one job the site must do", "Structure planned before the first prompt", "Design system defined", "All sections built", "Responsive QA at three widths", "Accessibility pass: keyboard, contrast, labels", "Performance pass: images, fonts, layout shift", "Deployed and reachable at a public URL", "Final read-through of every line of copy"]}'::jsonb, 'Eindproject — bouw je eigen complete website', 'Een echte klantbriefing. Alles uit de cursus, in één build, online onder je eigen naam.', '{"client": "Een fictief creatief bedrijf naar keuze. Geef het een naam, geef het een standpunt, en schrijf de teksten zelf.", "goal": "Een complete website die je aan een betalende klant durft voor te leggen.", "requirements": ["Responsive van 360px tot 1920px", "Een bewust typesysteem, geen standaardwaarden", "Werkende navigatie op mobiel", "Beweging die de content dient en reduced motion respecteert", "Interacties die echt werken — geen versiering die zich voordoet als bedieningselement", "Toegankelijk met het toetsenbord, met zichtbare focus", "Snel: geen te zware bestanden, geen layout shift", "Gedeployed naar een live URL"], "prompts": ["project-scaffold", "design-system", "responsive-pass", "final-qa"], "checklist": ["Briefing geschreven: klant, publiek, de ene taak die de site moet doen", "Structuur gepland vóór de eerste prompt", "Designsysteem gedefinieerd", "Alle secties gebouwd", "Responsive QA op drie breedtes", "Toegankelijkheidsronde: toetsenbord, contrast, labels", "Performanceronde: afbeeldingen, fonts, layout shift", "Gedeployed en bereikbaar op een openbare URL", "Elke regel tekst nog één keer doorgelezen"]}'::jsonb, true, 4, true)
insert into public.prompts (id, slug, category, title, purpose, body, explanation, title_nl, purpose_nl, body_nl, explanation_nl, position) values
  ('0210a709-404e-59d8-8603-cc1a9ae96cf3', 'project-scaffold', 'Start', 'Start a project from nothing', 'Opens a session with enough context that the first result is worth editing.', 'I am building a one-page website for {WHO}. Their visitors are {AUDIENCE}, and the single thing the page must get them to do is {ACTION}.
insert into public.quizzes (id, level_id, lesson_id, slug, title, subtitle, title_nl, subtitle_nl, passing_score, published, position) values
  ('c9d1244d-1be8-592e-8411-cb8f0642a19e', '0117796f-d1ee-5e5a-8132-f58c5592b527', null, 'foundation-assessment', 'Foundation Assessment', 'Do you know what you are building?', 'Basistoets', 'Weet je wat je bouwt?', 70, true, 1),
  ('436247bf-97eb-5bee-a647-78ed93882f64', 'dc1a60ee-68f1-5dfe-908c-65b35b975f35', null, 'claude-fundamentals', 'Claude Fundamentals', 'Can you direct a model?', 'Claude-basis', 'Kun jij een model aansturen?', 70, true, 2),
  ('fbb41c48-07b7-5c93-8924-7f89d35b6489', 'd6c8b7b8-d769-54cf-9cf3-f6a1f8f59db0', null, 'prompt-engineering-assessment', 'Prompt Engineering Assessment', 'Nine shapes, one session.', 'Toets prompt engineering', 'Negen vormen, één sessie.', 70, false, 3),
  ('acc5dc73-fa24-51e1-b5bd-74d8864ce395', 'b879945d-7b93-55d1-b6e5-878439a89c29', null, 'debugging-challenge', 'Debugging Challenge', 'Find the cause, not the symptom.', 'Debug-uitdaging', 'Vind de oorzaak, niet het symptoom.', 70, false, 4),
  ('3182f979-88a4-5f54-b4ca-11567204e941', '0e3df840-08ac-5805-9967-87d6016c8ea8', null, 'final-assessment', 'Final Assessment', 'Everything, at once.', 'Eindtoets', 'Alles, in één keer.', 70, false, 5)
insert into public.quiz_questions (id, quiz_id, question, type, explanation, question_nl, explanation_nl, points, position) values
  ('9e4df0c5-451c-5c71-9b2a-630de4b1f69f', 'c9d1244d-1be8-592e-8411-cb8f0642a19e', 'A browser has downloaded index.html, styles.css and script.js. Which one decides what the page *means*?', 'single', 'HTML carries the structure and meaning — headings, paragraphs, links, buttons. CSS decides how that meaning looks, JavaScript decides how it behaves. A screen reader, a search engine and a browser with CSS disabled all still get the meaning from the HTML alone.', 'Een browser heeft index.html, styles.css en script.js gedownload. Welke daarvan bepaalt wat de pagina *betekent*?', 'HTML draagt de structuur en de betekenis — koppen, alinea''s, links, knoppen. CSS bepaalt hoe die betekenis eruitziet, JavaScript bepaalt hoe die zich gedraagt. Een schermlezer, een zoekmachine en een browser met CSS uitgeschakeld halen de betekenis alle drie nog steeds uit de HTML alleen.', 1, 1),
  ('493761b7-d148-5cb1-96db-2f7879ecda91', 'c9d1244d-1be8-592e-8411-cb8f0642a19e', 'Which of these run on the visitor''s own device rather than on a server? Select all that apply.', 'multi', 'CSS and JavaScript execute in the visitor''s browser, which is why anything the browser can see, the visitor can see. Checking a password and storing data happen on a server precisely because they must not be under the visitor''s control.', 'Welke hiervan draaien op het apparaat van de bezoeker zelf en niet op een server? Selecteer alles wat van toepassing is.', 'CSS en JavaScript draaien in de browser van de bezoeker. Daarom kan de bezoeker alles zien wat de browser kan zien. Een wachtwoord controleren en data opslaan gebeuren op een server, juist omdat ze niet in handen van de bezoeker mogen liggen.', 1, 2),
  ('1ca65de1-9fa4-5c00-8c31-b4f1fd8a055e', 'c9d1244d-1be8-592e-8411-cb8f0642a19e', 'If code appears in the browser''s Sources panel, a visitor can read it.', 'tf', 'Anything the browser downloads is readable by whoever is using the browser. This is the single most useful security fact for a front-end developer: never put a secret in code the browser receives.', 'Als code in het Sources-paneel van de browser verschijnt, kan een bezoeker hem lezen.', 'Alles wat de browser downloadt, is leesbaar voor wie die browser gebruikt. Dit is het nuttigste beveiligingsfeit voor een front-end developer: zet nooit een geheim in code die de browser ontvangt.', 1, 3),
  ('f5898046-caa0-5b0e-8087-8d7f7c15a2bc', 'c9d1244d-1be8-592e-8411-cb8f0642a19e', 'Claude returns a page that looks right but uses one 4MB photograph as the hero background. What is the honest description of what happened?', 'single', 'The model optimises for what you specified. Performance was not in the brief, so it was not in the output. Almost every complaint about AI-generated code is really a missing constraint.', 'Claude levert een pagina die er goed uitziet, maar gebruikt één foto van 4MB als achtergrond van de hero. Wat is de eerlijke beschrijving van wat er is gebeurd?', 'Het model optimaliseert voor wat jij hebt opgegeven. Performance stond niet in de briefing, dus stond het niet in het resultaat. Bijna elke klacht over door AI gegenereerde code is in werkelijkheid een ontbrekende beperking.', 1, 4),
  ('00117637-fea7-5212-afdf-0a157167cfae', 'c9d1244d-1be8-592e-8411-cb8f0642a19e', 'You are about to build a page for a bakery. You have one hour. What do you do first?', 'scenario', 'Every later decision — layout, hierarchy, what gets cut — resolves against the answer to that question. An hour spent building the wrong page is an hour gone; five minutes deciding what the page is for is what makes the other fifty-five useful.', 'Je gaat een pagina bouwen voor een bakkerij. Je hebt één uur. Wat doe je als eerste?', 'Elke latere beslissing — layout, hiërarchie, wat sneuvelt — wordt afgewogen tegen het antwoord op die vraag. Een uur besteed aan de verkeerde pagina is een uur weg. Vijf minuten bepalen waar de pagina voor is, maakt de andere vijfenvijftig bruikbaar.', 1, 5),
  ('1b8e7316-b858-5f14-8c82-d97dd7fdbb43', 'c9d1244d-1be8-592e-8411-cb8f0642a19e', 'Which of these is genuinely outside what Claude can do for you?', 'single', 'Taste, context about a specific person, and responsibility for the decision stay with you. That is not a limitation to work around — it is the part of the job that remains yours.', 'Wat valt echt buiten wat Claude voor je kan doen?', 'Smaak, kennis van een specifiek persoon en verantwoordelijkheid voor de beslissing blijven bij jou. Dat is geen beperking om omheen te werken — het is het deel van het werk dat van jou blijft.', 1, 6),
  ('b25dda1d-1880-5f4b-b2be-68329512ca99', 'c9d1244d-1be8-592e-8411-cb8f0642a19e', 'Which steps belong in an AI development workflow *before* you ask for any code? Select all that apply.', 'multi', 'Goal, context and constraints all come before the first request. Inspecting output is step seven — it cannot happen until something exists, and it is the step people skip most often.', 'Welke stappen horen in een AI-ontwikkelworkflow thuis *voordat* je om code vraagt? Selecteer alles wat van toepassing is.', 'Doel, context en beperkingen komen allemaal vóór het eerste verzoek. Het resultaat bekijken is stap zeven — dat kan pas als er iets bestaat, en het is de stap die mensen het vaakst overslaan.', 1, 7),
  ('612bbe89-1d2b-58d6-afa0-e167f769c849', 'c9d1244d-1be8-592e-8411-cb8f0642a19e', 'Frontend and backend is a distinction about where code runs, not about how difficult it is.', 'tf', 'Front end runs on the visitor''s device; back end runs on a machine you control. Difficulty has nothing to do with it — a front-end animation system can be far harder than a CRUD endpoint.', 'Front-end en back-end is een onderscheid over waar code draait, niet over hoe moeilijk het is.', 'Front-end draait op het apparaat van de bezoeker, back-end op een machine die jij beheert. Moeilijkheid heeft er niets mee te maken — een front-end animatiesysteem kan veel lastiger zijn dan een CRUD-endpoint.', 1, 8),
  ('bd83fecd-697f-5ef9-af0a-9ff23431d00f', 'c9d1244d-1be8-592e-8411-cb8f0642a19e', 'You ask for a landing page and get one that is technically fine but reads like every other landing page. What is the most useful next move?', 'single', 'Generic output is the average of everything the model has seen, which is exactly what you get when nothing rules anything out. Every constraint you add removes a wrong answer.', 'Je vraagt om een landingspagina en krijgt er een die technisch prima is, maar leest als elke andere landingspagina. Wat is de nuttigste volgende zet?', 'Generiek werk is het gemiddelde van alles wat het model heeft gezien, en dat is precies wat je krijgt als niets iets uitsluit. Elke beperking die je toevoegt, haalt een verkeerd antwoord weg.', 1, 9),
  ('5c1a1e69-f662-55cd-b470-f86310bb869e', 'c9d1244d-1be8-592e-8411-cb8f0642a19e', 'What is the practical reason to read generated code rather than only running it?', 'single', 'You do not need to be able to write it from memory. You need to be able to change it on request, judge whether it is any good, and predict what a change will affect. That is the whole difference between owning a site and merely possessing one.', 'Wat is de praktische reden om gegenereerde code te lezen in plaats van hem alleen uit te voeren?', 'Je hoeft hem niet uit je hoofd te kunnen schrijven. Je moet hem op verzoek kunnen aanpassen, kunnen beoordelen of hij deugt, en kunnen voorspellen wat een wijziging raakt. Dat is het hele verschil tussen een site die van jou is en een site die je alleen maar hebt.', 1, 10),
  ('cc0d4cd6-2759-5126-abf1-e6caf7d5e3bf', '436247bf-97eb-5bee-a647-78ed93882f64', 'Which prompt gives Claude the most useful context?', 'prompt', 'Only the third names the audience, the emotional state they arrive in, the single action, and what to avoid. The fourth names structure but leaves every judgement call open — and structure without intent is how you get a page that is organised and still says nothing.', 'Welke prompt geeft Claude de nuttigste context?', 'Alleen de derde noemt het publiek, de gemoedstoestand waarin het binnenkomt, de ene actie en wat je moet vermijden. De vierde noemt structuur, maar laat elke afweging open — en structuur zonder intentie is hoe je een pagina krijgt die netjes geordend is en toch niets zegt.', 1, 1),
  ('00eb7b5b-15e2-5477-9c05-25588395e3df', '436247bf-97eb-5bee-a647-78ed93882f64', 'What actually happens when you say ''remember what we discussed earlier'' in a fresh conversation?', 'single', 'Context is what is in the current conversation, nothing more. This is why re-establishing context at the start of a session is a skill, not a chore.', 'Wat gebeurt er werkelijk als je in een nieuw gesprek zegt: ''denk aan wat we eerder hebben besproken''?', 'Context is wat er in het huidige gesprek staat, meer niet. Daarom is context opnieuw opbouwen aan het begin van een sessie een vaardigheid, geen corvee.', 1, 2),
  ('edf4e273-257d-5eef-919b-8b5dc6610a03', '436247bf-97eb-5bee-a647-78ed93882f64', 'Which of these are constraints, in the useful sense? Select all that apply.', 'multi', 'A constraint rules something out in a way you could check afterwards. ''Make it look nice'' rules nothing out and cannot be verified, so it changes nothing about the output.', 'Welke hiervan zijn beperkingen, in de nuttige zin van het woord? Selecteer alles wat van toepassing is.', 'Een beperking sluit iets uit op een manier die je achteraf kunt controleren. ''Maak het mooi'' sluit niets uit en is niet te verifiëren, dus het verandert niets aan het resultaat.', 1, 3),
  ('4e1a7625-1deb-5149-bc43-db4c2eea5e79', '436247bf-97eb-5bee-a647-78ed93882f64', 'You paste 400 lines of your own CSS and ask for a change to one component. What should you do to get a reliable answer?', 'single', 'Working with existing code is mostly about fencing the change. Naming what must stay the same is what stops a helpful model from redesigning three things you liked.', 'Je plakt 400 regels van je eigen CSS en vraagt om een wijziging aan één component. Wat doe je om een betrouwbaar antwoord te krijgen?', 'Werken met bestaande code draait vooral om het afbakenen van de wijziging. Benoemen wat hetzelfde moet blijven, is wat een behulpzaam model ervan weerhoudt drie dingen te herontwerpen die je juist goed vond.', 1, 4),
  ('8edc01e4-f730-5269-8343-d66f18c62c7d', '436247bf-97eb-5bee-a647-78ed93882f64', 'A longer prompt is always a better prompt.', 'tf', 'Length is a side effect, not the goal. A long prompt full of adjectives is still vague; a short prompt that names the audience, the action and two hard constraints is not.', 'Een langere prompt is altijd een betere prompt.', 'Lengte is een bijeffect, geen doel. Een lange prompt vol bijvoeglijke naamwoorden is nog steeds vaag. Een korte prompt die het publiek, de actie en twee harde beperkingen noemt, is dat niet.', 1, 5),
  ('93480080-6a08-51dd-a918-ac194fcf9b5e', '436247bf-97eb-5bee-a647-78ed93882f64', 'Which sentence gives real design direction?', 'single', 'The third names decisions a developer could act on and you could check. ''Modern and clean'' and ''like Apple'' are compliments, not instructions — and the model will resolve them into the most average version of that idea.', 'Welke zin geeft echte ontwerprichting?', 'De derde noemt beslissingen waar een developer mee aan de slag kan en die jij kunt controleren. ''Modern en clean'' en ''zoals Apple'' zijn complimenten, geen instructies — en het model vertaalt ze naar de meest gemiddelde versie van dat idee.', 1, 6),
  ('39b34af8-448a-54b5-b99c-1df5867dc8f1', '436247bf-97eb-5bee-a647-78ed93882f64', 'Claude gives you a component that works, but the class names clash with your existing system. What is the highest-value response?', 'scenario', 'Conventions are context. Stating one once and reusing it turns a series of one-off corrections into a session that stays on your rails.', 'Claude geeft je een component dat werkt, maar de klassennamen botsen met je bestaande systeem. Welke reactie levert het meeste op?', 'Conventies zijn context. Er één keer een uitspreken en hem daarna hergebruiken verandert een reeks losse correcties in een sessie die op jouw rails blijft.', 1, 7),
  ('5ed4211d-954d-58f1-b982-6e0df19cdbf4', '436247bf-97eb-5bee-a647-78ed93882f64', 'Which parts belong in a first development prompt? Select all that apply.', 'multi', 'Goal, audience and exclusions all change the output. Politeness does not — it is fine to be polite, but it is not doing any work.', 'Welke onderdelen horen in een eerste ontwikkelprompt? Selecteer alles wat van toepassing is.', 'Doel, publiek en uitsluitingen veranderen allemaal het resultaat. Beleefdheid niet — beleefd zijn mag, maar het doet geen werk.', 1, 8),
  ('d59efdc1-4e6c-5b4e-90e4-4d30223d3098', '436247bf-97eb-5bee-a647-78ed93882f64', 'You want three variations of a hero to choose between. What is the reliable way to ask?', 'single', 'Naming the axis — layout, tone, density — makes the variations genuinely different and comparable. ''Some options'' produces three versions of the same idea.', 'Je wilt drie varianten van een hero om uit te kiezen. Wat is de betrouwbare manier om dat te vragen?', 'De as benoemen — layout, toon, dichtheid — maakt de varianten echt verschillend en vergelijkbaar. ''Wat opties'' levert drie versies van hetzelfde idee op.', 1, 9),
  ('315efdff-cdaf-5b0b-876e-8d7c55706394', '436247bf-97eb-5bee-a647-78ed93882f64', 'If the first result is wrong, the fastest fix is usually to rewrite the prompt rather than to describe the problem.', 'tf', 'Describing what is wrong keeps everything that was right. Rewriting from scratch throws away the parts you had already got working, and often reintroduces problems you had already fixed.', 'Als het eerste resultaat fout is, is de snelste oplossing meestal de prompt herschrijven in plaats van het probleem beschrijven.', 'Beschrijven wat er mis is, behoudt alles wat goed was. Opnieuw beginnen gooit de delen weg die je al werkend had, en brengt vaak problemen terug die je al had opgelost.', 1, 10)
insert into public.quiz_answers (id, question_id, answer, answer_nl, is_correct, position) values
  ('c20613ef-c4aa-576d-8c41-4256bd726fdc', '9e4df0c5-451c-5c71-9b2a-630de4b1f69f', 'index.html', 'index.html', true, 1),
